IF i_enable THEN
	P_num:=F_num+T_num;

	IF P_num<=0 THEN
	    out_bool:=FALSE;
	ELSE
	    run_num:=run_num+1;
	    out_bool:=(run_num>F_num);
	END_IF

	IF run_num>=P_num THEN
	   	 run_num:=0;
	END_IF

ELSE 
	out_bool:=FALSE;	
	run_num:=0;
END_IF

// ===================================================================
// TCP INPUT_REGISTER 地址布局 (PLC → PC, V5.0)
// ===================================================================
// 设计原则:
//   - 每节内字段从基址连续紧排, 节尾留大块预留
//   - 节边界对齐 32W 倍数, 便于上位机分块读取
//   - 字段一旦发布不再挪位; 新字段从节末预留区追加
//   - [E] 指令回读区与 PC→PLC 区 [C][D][E] 一一对应, 让 HMI 验证收发一致
// ===================================================================
// [A] 系统状态     0   – 31    (32 W; 10 字段 = 20 W, 余 12 W)
// [B] 油路实时    32   – 95    (64 W; 11 标量 + 10 元 1ms 压力数组 = 42 W, 余 22 W)
// [C] 控制器分量  96   – 127   (32 W;  4 字段 =  8 W, 余 24 W)
// [D] 液压站实时 128  – 159    (32 W;  6 字段 = 12 W, 余 20 W)
// [E] 指令回读   160  – 223    (64 W; 26 字段 = 52 W, 余 12 W)
// [F] 系统诊断   224  – 255    (32 W;  4 字段 =  8 W, 余 24 W)
// [G] 设备状态   256  – 319    (64 W; 由 PRG_DeviceControl 填充)
// [Z] 未来扩展   320  – 1999
// ===================================================================


// ===== [A] 系统状态 (0-31) =====
j := 0;

Float_to_TwoWord(input := GVL_PulsePressure.PP_FrameCounter_PLC);
INPUT_REGISTER[j]   := Float_to_TwoWord.Word_LOW;
INPUT_REGISTER[j+1] := Float_to_TwoWord.Word_HIGH;         // 0-1: PLC 帧计数器 (心跳)
j := j + 2;

Float_to_TwoWord(input := GVL_PulsePressure.PP_SysState);
INPUT_REGISTER[j]   := Float_to_TwoWord.Word_LOW;
INPUT_REGISTER[j+1] := Float_to_TwoWord.Word_HIGH;         // 2-3: 系统状态 0=空闲 1=冲洗 3=运行 4=停止 5=故障 (无 2)
j := j + 2;

Float_to_TwoWord(input := GVL_PulsePressure.PP_AlarmFlags);
INPUT_REGISTER[j]   := Float_to_TwoWord.Word_LOW;
INPUT_REGISTER[j+1] := Float_to_TwoWord.Word_HIGH;         // 4-5: 报警标志
j := j + 2;

Float_to_TwoWord(input := GVL_PulsePressure.PP_TotalCyclesDone);
INPUT_REGISTER[j]   := Float_to_TwoWord.Word_LOW;
INPUT_REGISTER[j+1] := Float_to_TwoWord.Word_HIGH;         // 6-7: 累计循环次数
j := j + 2;

Float_to_TwoWord(input := GVL_PulsePressure.PP_SysCommand);
INPUT_REGISTER[j]   := Float_to_TwoWord.Word_LOW;
INPUT_REGISTER[j+1] := Float_to_TwoWord.Word_HIGH;         // 8-9: 系统命令回读
j := j + 2;

Float_to_TwoWord(input := GVL_PulsePressure.PP_Enable);
INPUT_REGISTER[j]   := Float_to_TwoWord.Word_LOW;
INPUT_REGISTER[j+1] := Float_to_TwoWord.Word_HIGH;         // 10-11: 使能回读
j := j + 2;

Float_to_TwoWord(input := GVL_PulsePressure.PP_IO_InputBits);
INPUT_REGISTER[j]   := Float_to_TwoWord.Word_LOW;
INPUT_REGISTER[j+1] := Float_to_TwoWord.Word_HIGH;         // 12-13: 数字量输入
j := j + 2;

Float_to_TwoWord(input := GVL_PulsePressure.PP_IO_OutputBits_FB);
INPUT_REGISTER[j]   := Float_to_TwoWord.Word_LOW;
INPUT_REGISTER[j+1] := Float_to_TwoWord.Word_HIGH;         // 14-15: 数字量输出回读
j := j + 2;

Float_to_TwoWord(input := GVL_PulsePressure.PP_FlushTimeRemaining);
INPUT_REGISTER[j]   := Float_to_TwoWord.Word_LOW;
INPUT_REGISTER[j+1] := Float_to_TwoWord.Word_HIGH;         // 16-17: 冲洗排气剩余时间 (s)
j := j + 2;

Float_to_TwoWord(input := GVL_PulsePressure.PP_StateReady);
INPUT_REGISTER[j]   := Float_to_TwoWord.Word_LOW;
INPUT_REGISTER[j+1] := Float_to_TwoWord.Word_HIGH;         // 18-19: 状态推进就绪标志
j := j + 2;

// 20-31: 保留 (6 字段)


// ===== [B] 油路实时 (32-95) =====
j := 32;

Float_to_TwoWord(input := GVL_PulsePressure.PP_Oil_ActualPressure);
INPUT_REGISTER[j]   := Float_to_TwoWord.Word_LOW;
INPUT_REGISTER[j+1] := Float_to_TwoWord.Word_HIGH;         // 32-33: 油路实际压力 (MPa)
j := j + 2;

Float_to_TwoWord(input := GVL_PulsePressure.PP_Oil_SetpointPressure);
INPUT_REGISTER[j]   := Float_to_TwoWord.Word_LOW;
INPUT_REGISTER[j+1] := Float_to_TwoWord.Word_HIGH;         // 34-35: 油路给定压力 (MPa)
j := j + 2;

Float_to_TwoWord(input := GVL_PulsePressure.PP_Oil_PressureError);
INPUT_REGISTER[j]   := Float_to_TwoWord.Word_LOW;
INPUT_REGISTER[j+1] := Float_to_TwoWord.Word_HIGH;         // 36-37: 油路压力偏差 (MPa)
j := j + 2;

Float_to_TwoWord(input := GVL_PulsePressure.PP_Oil_ControlOutput);
INPUT_REGISTER[j]   := Float_to_TwoWord.Word_LOW;
INPUT_REGISTER[j+1] := Float_to_TwoWord.Word_HIGH;         // 38-39: 阀控总输出 (V) = PID
j := j + 2;

Float_to_TwoWord(input := GVL_PulsePressure.PP_Oil_ValveCurrent);
INPUT_REGISTER[j]   := Float_to_TwoWord.Word_LOW;
INPUT_REGISTER[j+1] := Float_to_TwoWord.Word_HIGH;         // 40-41: 比例阀电流 (mA)
j := j + 2;

Float_to_TwoWord(input := GVL_PulsePressure.PP_Oil_CyclesDone);
INPUT_REGISTER[j]   := Float_to_TwoWord.Word_LOW;
INPUT_REGISTER[j+1] := Float_to_TwoWord.Word_HIGH;         // 42-43: 完成循环次数
j := j + 2;

Float_to_TwoWord(input := GVL_PulsePressure.PP_Oil_Frequency_FB);
INPUT_REGISTER[j]   := Float_to_TwoWord.Word_LOW;
INPUT_REGISTER[j+1] := Float_to_TwoWord.Word_HIGH;         // 44-45: 实际频率 (Hz)
j := j + 2;

Float_to_TwoWord(input := GVL_PulsePressure.PP_Oil_WavePhase);
INPUT_REGISTER[j]   := Float_to_TwoWord.Word_LOW;
INPUT_REGISTER[j+1] := Float_to_TwoWord.Word_HIGH;         // 46-47: 波形相位 (°)
j := j + 2;

Float_to_TwoWord(input := GVL_PulsePressure.PP_Oil_PeakPressure);
INPUT_REGISTER[j]   := Float_to_TwoWord.Word_LOW;
INPUT_REGISTER[j+1] := Float_to_TwoWord.Word_HIGH;         // 48-49: 本次脉冲峰值 (MPa)
j := j + 2;

Float_to_TwoWord(input := GVL_PulsePressure.PP_Oil_TargetUpper);
INPUT_REGISTER[j]   := Float_to_TwoWord.Word_LOW;
INPUT_REGISTER[j+1] := Float_to_TwoWord.Word_HIGH;         // 50-51: ARP1383C 上包络 (MPa)
j := j + 2;

Float_to_TwoWord(input := GVL_PulsePressure.PP_Oil_TargetLower);
INPUT_REGISTER[j]   := Float_to_TwoWord.Word_LOW;
INPUT_REGISTER[j+1] := Float_to_TwoWord.Word_HIGH;         // 52-53: ARP1383C 下包络 (MPa)
j := j + 2;

// -- 1ms 分辨率压力缓冲 (10 采样, 54-73) --
// PLC 1ms 任务采样, TCP 10ms 任务在每个通讯周期发送上一窗口的 10 个点
// 索引: [0]=窗口起点(t-9ms), [9]=窗口终点(t-0ms, 最新)
Float_to_TwoWord(input := GVL_PulsePressure.PP_Oil_ActualPressure_1ms[0]);
INPUT_REGISTER[j]   := Float_to_TwoWord.Word_LOW;
INPUT_REGISTER[j+1] := Float_to_TwoWord.Word_HIGH;         // 54-55: 1ms 压力 [0] t-9ms
j := j + 2;

Float_to_TwoWord(input := GVL_PulsePressure.PP_Oil_ActualPressure_1ms[1]);
INPUT_REGISTER[j]   := Float_to_TwoWord.Word_LOW;
INPUT_REGISTER[j+1] := Float_to_TwoWord.Word_HIGH;         // 56-57: 1ms 压力 [1] t-8ms
j := j + 2;

Float_to_TwoWord(input := GVL_PulsePressure.PP_Oil_ActualPressure_1ms[2]);
INPUT_REGISTER[j]   := Float_to_TwoWord.Word_LOW;
INPUT_REGISTER[j+1] := Float_to_TwoWord.Word_HIGH;         // 58-59: 1ms 压力 [2] t-7ms
j := j + 2;

Float_to_TwoWord(input := GVL_PulsePressure.PP_Oil_ActualPressure_1ms[3]);
INPUT_REGISTER[j]   := Float_to_TwoWord.Word_LOW;
INPUT_REGISTER[j+1] := Float_to_TwoWord.Word_HIGH;         // 60-61: 1ms 压力 [3] t-6ms
j := j + 2;

Float_to_TwoWord(input := GVL_PulsePressure.PP_Oil_ActualPressure_1ms[4]);
INPUT_REGISTER[j]   := Float_to_TwoWord.Word_LOW;
INPUT_REGISTER[j+1] := Float_to_TwoWord.Word_HIGH;         // 62-63: 1ms 压力 [4] t-5ms
j := j + 2;

Float_to_TwoWord(input := GVL_PulsePressure.PP_Oil_ActualPressure_1ms[5]);
INPUT_REGISTER[j]   := Float_to_TwoWord.Word_LOW;
INPUT_REGISTER[j+1] := Float_to_TwoWord.Word_HIGH;         // 64-65: 1ms 压力 [5] t-4ms
j := j + 2;

Float_to_TwoWord(input := GVL_PulsePressure.PP_Oil_ActualPressure_1ms[6]);
INPUT_REGISTER[j]   := Float_to_TwoWord.Word_LOW;
INPUT_REGISTER[j+1] := Float_to_TwoWord.Word_HIGH;         // 66-67: 1ms 压力 [6] t-3ms
j := j + 2;

Float_to_TwoWord(input := GVL_PulsePressure.PP_Oil_ActualPressure_1ms[7]);
INPUT_REGISTER[j]   := Float_to_TwoWord.Word_LOW;
INPUT_REGISTER[j+1] := Float_to_TwoWord.Word_HIGH;         // 68-69: 1ms 压力 [7] t-2ms
j := j + 2;

Float_to_TwoWord(input := GVL_PulsePressure.PP_Oil_ActualPressure_1ms[8]);
INPUT_REGISTER[j]   := Float_to_TwoWord.Word_LOW;
INPUT_REGISTER[j+1] := Float_to_TwoWord.Word_HIGH;         // 70-71: 1ms 压力 [8] t-1ms
j := j + 2;

Float_to_TwoWord(input := GVL_PulsePressure.PP_Oil_ActualPressure_1ms[9]);
INPUT_REGISTER[j]   := Float_to_TwoWord.Word_LOW;
INPUT_REGISTER[j+1] := Float_to_TwoWord.Word_HIGH;         // 72-73: 1ms 压力 [9] t-0ms (最新)
j := j + 2;

// 74-95: 保留 (11 字段)


// ===== [C] 控制器分量 (96-127) =====
j := 96;

Float_to_TwoWord(input := GVL_PulsePressure.PP_Oil_ILC_Output);
INPUT_REGISTER[j]   := Float_to_TwoWord.Word_LOW;
INPUT_REGISTER[j+1] := Float_to_TwoWord.Word_HIGH;         // 96-97: ILC 指令修正量 (MPa)
j := j + 2;

Float_to_TwoWord(input := GVL_PulsePressure.PP_Oil_ILC_Iteration);
INPUT_REGISTER[j]   := Float_to_TwoWord.Word_LOW;
INPUT_REGISTER[j+1] := Float_to_TwoWord.Word_HIGH;         // 98-99: ILC 当前迭代次数
j := j + 2;

Float_to_TwoWord(input := GVL_PulsePressure.PP_Oil_PID_Output);
INPUT_REGISTER[j]   := Float_to_TwoWord.Word_LOW;
INPUT_REGISTER[j+1] := Float_to_TwoWord.Word_HIGH;         // 100-101: PID 反馈输出 (V)
j := j + 2;

Float_to_TwoWord(input := GVL_PulsePressure.PP_Oil_PID_Integral);
INPUT_REGISTER[j]   := Float_to_TwoWord.Word_LOW;
INPUT_REGISTER[j+1] := Float_to_TwoWord.Word_HIGH;         // 102-103: PID 积分项 (V)
j := j + 2;

// 104-127: 保留 (12 字段)


// ===== [D] 液压站实时 (128-159) =====
j := 128;

Float_to_TwoWord(input := GVL_PulsePressure.PP_Hydro_Pressure);
INPUT_REGISTER[j]   := Float_to_TwoWord.Word_LOW;
INPUT_REGISTER[j+1] := Float_to_TwoWord.Word_HIGH;         // 128-129: 液压站系统压力 (MPa)
j := j + 2;

Float_to_TwoWord(input := GVL_PulsePressure.PP_Hydro_Temperature);
INPUT_REGISTER[j]   := Float_to_TwoWord.Word_LOW;
INPUT_REGISTER[j+1] := Float_to_TwoWord.Word_HIGH;         // 130-131: 液压油温度 (°C)
j := j + 2;

Float_to_TwoWord(input := GVL_PulsePressure.PP_Hydro_OilLevel);
INPUT_REGISTER[j]   := Float_to_TwoWord.Word_LOW;
INPUT_REGISTER[j+1] := Float_to_TwoWord.Word_HIGH;         // 132-133: 液位 (mm)
j := j + 2;

Float_to_TwoWord(input := GVL_PulsePressure.PP_Hydro_PumpStatus);
INPUT_REGISTER[j]   := Float_to_TwoWord.Word_LOW;
INPUT_REGISTER[j+1] := Float_to_TwoWord.Word_HIGH;         // 134-135: 液压泵运行状态
j := j + 2;

Float_to_TwoWord(input := GVL_PulsePressure.PP_Hydro_FilterStatus);
INPUT_REGISTER[j]   := Float_to_TwoWord.Word_LOW;
INPUT_REGISTER[j+1] := Float_to_TwoWord.Word_HIGH;         // 136-137: 过滤器状态
j := j + 2;

Float_to_TwoWord(input := GVL_PulsePressure.PP_Hydro_PumpRunTime);
INPUT_REGISTER[j]   := Float_to_TwoWord.Word_LOW;
INPUT_REGISTER[j+1] := Float_to_TwoWord.Word_HIGH;         // 138-139: 液压泵累计运行时间 (h)
j := j + 2;

// 140-159: 保留 (10 字段)


// ===== [E] 指令回读 (160-223) =====
// 镜像 PC→PLC 区 [C][D][E], 让上位机验证收发一致
// 顺序与 PC→PLC 一致, 但布局连续 (PC→PLC 节内的预留区在回读区不复制)
j := 160;

// -- 镜像 PC→PLC [C] 油路波形 (15 字段) --
Float_to_TwoWord(input := GVL_PulsePressure.PP_Oil_WaveType);
INPUT_REGISTER[j]   := Float_to_TwoWord.Word_LOW;
INPUT_REGISTER[j+1] := Float_to_TwoWord.Word_HIGH;         // 160-161: 波形类型 (回读)
j := j + 2;

Float_to_TwoWord(input := GVL_PulsePressure.PP_Oil_TargetPressure);
INPUT_REGISTER[j]   := Float_to_TwoWord.Word_LOW;
INPUT_REGISTER[j+1] := Float_to_TwoWord.Word_HIGH;         // 162-163: 目标峰值压力 (回读)
j := j + 2;

Float_to_TwoWord(input := GVL_PulsePressure.PP_Oil_MinPressure);
INPUT_REGISTER[j]   := Float_to_TwoWord.Word_LOW;
INPUT_REGISTER[j+1] := Float_to_TwoWord.Word_HIGH;         // 164-165: 最低压力 (回读)
j := j + 2;

Float_to_TwoWord(input := GVL_PulsePressure.PP_Oil_Frequency);
INPUT_REGISTER[j]   := Float_to_TwoWord.Word_LOW;
INPUT_REGISTER[j+1] := Float_to_TwoWord.Word_HIGH;         // 166-167: 频率 (回读)
j := j + 2;

Float_to_TwoWord(input := GVL_PulsePressure.PP_Oil_HighLimit);
INPUT_REGISTER[j]   := Float_to_TwoWord.Word_LOW;
INPUT_REGISTER[j+1] := Float_to_TwoWord.Word_HIGH;         // 168-169: 油路高压限值 (回读)
j := j + 2;

Float_to_TwoWord(input := GVL_PulsePressure.PP_Oil_TargetCycles);
INPUT_REGISTER[j]   := Float_to_TwoWord.Word_LOW;
INPUT_REGISTER[j+1] := Float_to_TwoWord.Word_HIGH;         // 170-171: 目标循环次数 (回读)
j := j + 2;

Float_to_TwoWord(input := GVL_PulsePressure.PP_Oil_RisePct);
INPUT_REGISTER[j]   := Float_to_TwoWord.Word_LOW;
INPUT_REGISTER[j+1] := Float_to_TwoWord.Word_HIGH;         // 172-173: 上升段占比 (回读)
j := j + 2;

Float_to_TwoWord(input := GVL_PulsePressure.PP_Oil_HoldPct);
INPUT_REGISTER[j]   := Float_to_TwoWord.Word_LOW;
INPUT_REGISTER[j+1] := Float_to_TwoWord.Word_HIGH;         // 174-175: 保压段占比 (回读)
j := j + 2;

Float_to_TwoWord(input := GVL_PulsePressure.PP_Oil_FallPct);
INPUT_REGISTER[j]   := Float_to_TwoWord.Word_LOW;
INPUT_REGISTER[j+1] := Float_to_TwoWord.Word_HIGH;         // 176-177: 下降段占比 (回读)
j := j + 2;

Float_to_TwoWord(input := GVL_PulsePressure.PP_Oil_Overshoot);
INPUT_REGISTER[j]   := Float_to_TwoWord.Word_LOW;
INPUT_REGISTER[j+1] := Float_to_TwoWord.Word_HIGH;         // 178-179: 过冲峰倍数 (回读)
j := j + 2;

Float_to_TwoWord(input := GVL_PulsePressure.PP_Oil_RingPct);
INPUT_REGISTER[j]   := Float_to_TwoWord.Word_LOW;
INPUT_REGISTER[j+1] := Float_to_TwoWord.Word_HIGH;         // 180-181: 过冲后稳定段占比 (回读)
j := j + 2;

Float_to_TwoWord(input := GVL_PulsePressure.PP_Oil_LowDwellPct);
INPUT_REGISTER[j]   := Float_to_TwoWord.Word_LOW;
INPUT_REGISTER[j+1] := Float_to_TwoWord.Word_HIGH;         // 182-183: 低保持段占比 (回读)
j := j + 2;

Float_to_TwoWord(input := GVL_PulsePressure.PP_Oil_CycleReset);
INPUT_REGISTER[j]   := Float_to_TwoWord.Word_LOW;
INPUT_REGISTER[j+1] := Float_to_TwoWord.Word_HIGH;         // 184-185: 循环计数清零 (回读)
j := j + 2;

Float_to_TwoWord(input := GVL_PulsePressure.PP_Oil_EnvPctP);
INPUT_REGISTER[j]   := Float_to_TwoWord.Word_LOW;
INPUT_REGISTER[j+1] := Float_to_TwoWord.Word_HIGH;         // 186-187: 包络压力容差 (回读)
j := j + 2;

Float_to_TwoWord(input := GVL_PulsePressure.PP_Oil_EnvPctT);
INPUT_REGISTER[j]   := Float_to_TwoWord.Word_LOW;
INPUT_REGISTER[j+1] := Float_to_TwoWord.Word_HIGH;         // 188-189: (已废弃) 原包络时间容差 (回读, 地址保留)
j := j + 2;

// -- 镜像 PC→PLC [D] 控制器 (6 字段) --
Float_to_TwoWord(input := GVL_PulsePressure.PP_Oil_ILC_Enable);
INPUT_REGISTER[j]   := Float_to_TwoWord.Word_LOW;
INPUT_REGISTER[j+1] := Float_to_TwoWord.Word_HIGH;         // 190-191: ILC 使能 (回读)
j := j + 2;

Float_to_TwoWord(input := GVL_PulsePressure.PP_Oil_ILC_MaxIter);
INPUT_REGISTER[j]   := Float_to_TwoWord.Word_LOW;
INPUT_REGISTER[j+1] := Float_to_TwoWord.Word_HIGH;         // 192-193: ILC 最大迭代 (回读)
j := j + 2;

Float_to_TwoWord(input := GVL_PulsePressure.PP_Oil_ILC_LearningRate);
INPUT_REGISTER[j]   := Float_to_TwoWord.Word_LOW;
INPUT_REGISTER[j+1] := Float_to_TwoWord.Word_HIGH;         // 194-195: ILC 学习率 (回读)
j := j + 2;

Float_to_TwoWord(input := GVL_PulsePressure.PP_Oil_PID_Kp);
INPUT_REGISTER[j]   := Float_to_TwoWord.Word_LOW;
INPUT_REGISTER[j+1] := Float_to_TwoWord.Word_HIGH;         // 196-197: PID Kp (回读)
j := j + 2;

Float_to_TwoWord(input := GVL_PulsePressure.PP_Oil_PID_Ki);
INPUT_REGISTER[j]   := Float_to_TwoWord.Word_LOW;
INPUT_REGISTER[j+1] := Float_to_TwoWord.Word_HIGH;         // 198-199: PID Ki (回读)
j := j + 2;

Float_to_TwoWord(input := GVL_PulsePressure.PP_Oil_PID_Kd);
INPUT_REGISTER[j]   := Float_to_TwoWord.Word_LOW;
INPUT_REGISTER[j+1] := Float_to_TwoWord.Word_HIGH;         // 200-201: PID Kd (回读)
j := j + 2;

// -- 镜像 PC→PLC [E] 液压站 (4 字段) --
Float_to_TwoWord(input := GVL_PulsePressure.PP_Hydro_HighLimit);
INPUT_REGISTER[j]   := Float_to_TwoWord.Word_LOW;
INPUT_REGISTER[j+1] := Float_to_TwoWord.Word_HIGH;         // 202-203: 液压站高压限值 (回读)
j := j + 2;

Float_to_TwoWord(input := GVL_PulsePressure.PP_Hydro_TempLimit);
INPUT_REGISTER[j]   := Float_to_TwoWord.Word_LOW;
INPUT_REGISTER[j+1] := Float_to_TwoWord.Word_HIGH;         // 204-205: 液压站温度限值 (回读)
j := j + 2;

Float_to_TwoWord(input := GVL_PulsePressure.PP_Hydro_PumpCmd);
INPUT_REGISTER[j]   := Float_to_TwoWord.Word_LOW;
INPUT_REGISTER[j+1] := Float_to_TwoWord.Word_HIGH;         // 206-207: 液压泵启停 (回读)
j := j + 2;

Float_to_TwoWord(input := GVL_PulsePressure.PP_Hydro_MotorSpeed);
INPUT_REGISTER[j]   := Float_to_TwoWord.Word_LOW;
INPUT_REGISTER[j+1] := Float_to_TwoWord.Word_HIGH;         // 208-209: 电机转速设定 (回读)
j := j + 2;

Float_to_TwoWord(input := GVL_PulsePressure.PP_Oil_Filter);
INPUT_REGISTER[j]   := Float_to_TwoWord.Word_LOW;
INPUT_REGISTER[j+1] := Float_to_TwoWord.Word_HIGH;         // 210-211: 油路滤波时间常数 (回读, ms)
j := j + 2;

// 212-223: 保留 (6 字段)


// ===== [F] 系统诊断 (224-255) =====
j := 224;

Float_to_TwoWord(input := GVL_PulsePressure.PP_PLC_ScanCycle);
INPUT_REGISTER[j]   := Float_to_TwoWord.Word_LOW;
INPUT_REGISTER[j+1] := Float_to_TwoWord.Word_HIGH;         // 224-225: PLC 扫描周期 (ms)
j := j + 2;

Float_to_TwoWord(input := GVL_PulsePressure.PP_TCPIP_CommCycle);
INPUT_REGISTER[j]   := Float_to_TwoWord.Word_LOW;
INPUT_REGISTER[j+1] := Float_to_TwoWord.Word_HIGH;         // 226-227: TCP 通讯周期 (ms)
j := j + 2;

Float_to_TwoWord(input := GVL_PulsePressure.PP_PLC_Timestamp_Low);
INPUT_REGISTER[j]   := Float_to_TwoWord.Word_LOW;
INPUT_REGISTER[j+1] := Float_to_TwoWord.Word_HIGH;         // 228-229: 时间戳低 32 位 (ms)
j := j + 2;

Float_to_TwoWord(input := GVL_PulsePressure.PP_PLC_Timestamp_High);
INPUT_REGISTER[j]   := Float_to_TwoWord.Word_LOW;
INPUT_REGISTER[j+1] := Float_to_TwoWord.Word_HIGH;         // 230-231: 时间戳高 32 位
j := j + 2;

// 232-255: 保留 (12 字段)


// ===== [G] 设备状态 (256-319) =====
// 该区域由 PRG_DeviceControl（待重写）填充
// 建议地址分配 (占位约定):
//   256-257 : bit-packed 泵运行/故障状态 (SMP/XH/HR1/HR2)
//   258-259 : bit-packed 过滤器状态 + 相序报警 (8.01/16.01/19.01/相序)
//   260-261 : 液压站油液温度
//   262-263 : 液压站油液液位
//   264-271 : 4 路油路压力传感器
//   272-279 : SMP 压力/转速/流量反馈
//   280-283 : HR_Pump1/Pump2 频率反馈
//   284-319 : 保留 (18 字段)


// ===== [Z] 320-1999: 未来扩展 =====

// ============================================================
// 复位 / 失能
// ============================================================
IF bReset OR NOT bEnable THEN
    rPhaseAcc := 0.0;
    rTarget := rPMin;
    rTargetPrev := rPMin;
    rTargetLast := rPMin;
    rTargetLead := rPMin;
    rTargetLeadPrev := rPMin;
    rTargetLeadLast := rPMin;
    rTargetUpper := rPMin;
    rTargetLower := rPMin;
    bNewCycle := FALSE;
    bFirstRun := TRUE;
    iIdxCounter := 0;
    RETURN;
END_IF

// 频率保护
IF rFrequency < 0.01 THEN
    rTarget := rPMin;
    rTargetPrev := rPMin;
    rTargetUpper := rPMin;
    rTargetLower := rPMin;
    RETURN;
END_IF

// 每周期采样点数
iPointsPerCycle := REAL_TO_INT(1.0 / (rFrequency * rDt));
IF iPointsPerCycle < 10 THEN
    iPointsPerCycle := 10;
END_IF

// 保存上一步值
rTargetPrev := rTargetLast;

// 相位推进 (使用累加器避免长时间漂移)
rPhaseAcc := rPhaseAcc + rFrequency * rDt;
IF rPhaseAcc >= 1.0 THEN
    rPhaseAcc := rPhaseAcc - 1.0;
    bNewCycle := TRUE;
    iIdxCounter := 0;
ELSE
    bNewCycle := FALSE;
END_IF

rPhase := rPhaseAcc;
iPointIndex := iIdxCounter;


// ============================================================
// 段宽参数归一化 (每周期算一次即可，每步算无害)
// ============================================================
CASE iWaveType OF

1:  // 梯形：4 段 (rR + rH + rF + rL = 1)
    rR := rRisePct;
    rH := rHoldPct;
    rF := rFallPct;
    IF rR < 0.01 THEN rR := 0.1; END_IF
    IF rH < 0.01 THEN rH := 0.3; END_IF
    IF rF < 0.01 THEN rF := 0.1; END_IF
    rL := 1.0 - rR - rH - rF;
    IF rL < 0.0 THEN rL := 0.0; END_IF
    // 梯形不用 rRing/rPeakOS，置零以防函数访问无效值
    rRing := 0.0;
    rPeakOS := rPMax;

2:  // 水锤：上升段斜坡到 P_OS, 段宽可由"上升速率"定; 其余 4 段相对权重填满
    // 过冲峰 P_OS 先算 (上升速率换算相位宽时要用):
    // ARP1383C 3.1: P_OS = 1.5×P_Oper (rPMax 即 P_Oper); 倍数可调, 写 <1 按 1.5
    rOS := rOvershoot;
    IF rOS < 1.0 THEN rOS := 1.5; END_IF
    rPeakOS := rOS * rPMax;

    rRing := rRingPct;
    rH := rHoldPct;
    rF := rFallPct;
    rLow := rLowDwellPct;
    IF rRing < 0.01 THEN rRing := 0.07; END_IF
    IF rH < 0.01 THEN rH := 0.35; END_IF
    IF rF < 0.01 THEN rF := 0.05; END_IF
    IF rLow < 0.01 THEN rLow := 0.48; END_IF

    IF rRiseRate > 0.0 THEN
        // 上升段按速率定宽: t_rise = (P_OS - PMin)/速率[MPa/s]; 相位宽 = t_rise × 频率
        rR := (rPeakOS - rPMin) / rRiseRate * rFrequency;
        IF rR < 0.002 THEN rR := 0.002; END_IF   // 速率过快 → 近似阶跃 (下限保护避免除零)
        IF rR > 0.5   THEN rR := 0.5;   END_IF   // 速率过慢 → 上限钳到半周期
        // 其余 4 段按相对权重填满剩余 (1 - rR)
        rSum := rRing + rH + rF + rLow;
        IF rSum > 0.01 THEN
            rRing := rRing / rSum * (1.0 - rR);
            rH    := rH    / rSum * (1.0 - rR);
            rF    := rF    / rSum * (1.0 - rR);
            rLow  := rLow  / rSum * (1.0 - rR);
        END_IF
    ELSE
        // 速率未给 (≤0): 退回 5 段相对权重归一化 (上升段仍为斜坡, 宽度由 rRisePct 定)
        rR := rRisePct;
        IF rR < 0.01 THEN rR := 0.05; END_IF
        rSum := rR + rRing + rH + rF + rLow;
        IF rSum > 0.01 THEN
            rR    := rR    / rSum;
            rRing := rRing / rSum;
            rH    := rH    / rSum;
            rF    := rF    / rSum;
            rLow  := rLow  / rSum;
        END_IF
    END_IF

ELSE
    // 正弦无段：把变量清成无害默认值
    rR := 0.0;
    rH := 0.0;
    rF := 0.0;
    rRing := 0.0;
    rPeakOS := rPMax;
END_CASE

// 段宽输出 (供下游 FB_ILC)
rSegRise   := rR;
rSegRing   := rRing;
rSegHold   := rH;
rSegFall   := rF;
rPeakOSOut := rPeakOS;


// ============================================================
// 主波形计算
// ============================================================
rTarget := FN_PulseWave(
    rPhaseIn := rPhase,
    rPMin := rPMin, rPMax := rPMax, iWaveType := iWaveType,
    rR := rR, rH := rH, rF := rF, rRing := rRing, rPeakOS := rPeakOS);


// ============================================================
// MFF 超前目标
// 用超前相位 (φ + N·Δφ) 计算未来 N 步的目标，给前馈控制器提前响应
// ============================================================
rTargetLeadPrev := rTargetLeadLast;

IF nMffLeadSteps > 0 THEN
    rPhaseLead := rPhaseAcc + INT_TO_REAL(nMffLeadSteps) * rFrequency * rDt;
    IF rPhaseLead >= 1.0 THEN rPhaseLead := rPhaseLead - 1.0; END_IF

    rTargetLead := FN_PulseWave(
        rPhaseIn := rPhaseLead,
        rPMin := rPMin, rPMax := rPMax, iWaveType := iWaveType,
        rR := rR, rH := rH, rF := rF, rRing := rRing, rPeakOS := rPeakOS);
ELSE
    rTargetLead := rTarget;
END_IF


// ============================================================
// ARP1383C 容差包络 — 按标准 Fig.1 / Fig.2 / Fig.3 阴影带生成
//
// 正弦  (Fig.3): 包络 = 真正弦整条曲线时移 ±0.05C + 压移 ±ΔP,
//               上下边界亦为正弦形、沿整条曲线等宽包裹标称 (非三角
//               近似)。峰/谷处时移钳到极值 → 平段 0.1C (最大驻留);
//               峰/谷垂直容差 ±ΔP (标准 0.02·PMax); PMean 处水平带宽
//               2·0.05C = 0.1C (最大畸变)。时移恒向极值 → 标称必在带内
// 梯形  (Fig.1 上图/供油腔): 保压带 [0.96, 1.04]·PMax; 低压段上限
//               1.1·PMin (不低于 0.345 MPa = 50 psi); 升沿: 上包络
//               提前 ENV_SLACK 到顶 / 下包络滞后 ENV_SLACK 到 0.96;
//               降沿: 下包络立即落 0, 上包络自下降结束后缓降至周期
//               末回到 1.1·PMin (允许实际压力长拖尾)
// 水锤  (Fig.2): 过冲峰+ring 段 (标准 0~15%C) 为全幅自由窗: 上包络
//               平直 1.04·P_OS (峰容差 ±4%, 峰值下限 0.96·P_OS 需另
//               行峰值检测)、下包络 0; 保压段上限 1.1·PMax / 下限
//               0.8→0.95·PMax 线性收紧; 下降窗 (标准 5%C) 亦为全幅
//               自由窗: 上包络保持 1.1·PMax 到窗尾、下包络立即落 0;
//               低压段 [0, 1.1·PMin]
// 注: Fig.1 保压带驻留 10%~37% 周期、Fig.3 试验条件 PMin=0.2·PMax
//     均为参数约束 (设参数时遵守), 不在包络内强制; Fig.1 下图回油
//     腔包络 (保压带 [0.9, 1.1]·PRMax, 低压上限 1.5·PMin) 本 FB 未
//     实现, 当前仅覆盖供油腔。
// ============================================================
rBaseUp := ENV_BASE_K * rPMin;
IF rBaseUp < ENV_BASE_MIN THEN rBaseUp := ENV_BASE_MIN; END_IF

CASE iWaveType OF

1:  // ---- 梯形 (Fig.1) ----
    rET1 := rR;             // 升沿结束
    rET2 := rR + rH;        // 保压结束 / 降沿开始
    rET3 := rR + rH + rF;   // 降沿结束

    // 上包络: (0, 1.1·PMin) → (T1-slack, 1.04·PMax) → 平 → (T3) → 缓降 → (1, 1.1·PMin)
    IF rPhase < rET1 - ENV_SLACK THEN
        rTargetUpper := rBaseUp + (ENV_TRAP_UP * rPMax - rBaseUp) * rPhase / (rET1 - ENV_SLACK);
    ELSIF rPhase < rET3 THEN
        rTargetUpper := ENV_TRAP_UP * rPMax;
    ELSIF rET3 < 0.999 THEN
        rTargetUpper := ENV_TRAP_UP * rPMax
                      + (rBaseUp - ENV_TRAP_UP * rPMax) * (rPhase - rET3) / (1.0 - rET3);
    ELSE
        rTargetUpper := rBaseUp;
    END_IF

    // 下包络: (0, 0) → (T1+slack, 0.96·PMax) → 平 → (T2) → (T2+slack, 0) → 0
    IF rPhase < rET1 + ENV_SLACK THEN
        rTargetLower := ENV_TRAP_LO * rPMax * rPhase / (rET1 + ENV_SLACK);
    ELSIF rPhase < rET2 THEN
        rTargetLower := ENV_TRAP_LO * rPMax;
    ELSIF rPhase < rET2 + ENV_SLACK THEN
        rTargetLower := ENV_TRAP_LO * rPMax * (1.0 - (rPhase - rET2) / ENV_SLACK);
    ELSE
        rTargetLower := 0.0;
    END_IF

2:  // ---- 水锤 (Fig.2) ----
    rET1 := rR;                      // 过冲峰段结束
    rET2 := rR + rRing;              // ring 段结束
    rET3 := rR + rRing + rH;         // 保压结束 / 下降开始
    rET4 := rR + rRing + rH + rF;    // 下降结束

    // 上包络: 峰+ring 整窗平直 1.04·P_OS (标准 0~15%C 全幅自由窗)
    //         → 保压/下降 1.1·PMax (上包络保持到下降段尾 = 标准 5%C 窗口)
    //         → 低压 1.1·PMin
    IF rPhase < rET2 THEN
        rTargetUpper := (1.0 + ENV_WH_PKTOL) * rPeakOS;
    ELSIF rPhase < rET4 THEN
        rTargetUpper := ENV_WH_UP * rPMax;
    ELSE
        rTargetUpper := rBaseUp;
    END_IF

    // 下包络: 峰+ring 整窗 0 (上升/振荡稳定自由窗)
    //         → 保压 0.8→0.95·PMax 线性收紧 (下降沿处达 0.95)
    //         → 下降窗起即落 0 (Fig.2 下降窗为全幅自由窗) → 低压 0
    IF rPhase < rET2 THEN
        rTargetLower := 0.0;
    ELSIF rPhase < rET3 THEN
        rTargetLower := ENV_WH_RINGLO * rPMax
                      + (ENV_WH_HOLDLO - ENV_WH_RINGLO) * rPMax * (rPhase - rET2) / (rET3 - rET2);
    ELSE
        rTargetLower := 0.0;
    END_IF

ELSE  // ---- 正弦 (Fig.3), 含未知类型兜底 ----
    // 包络 = 真正弦整条曲线时移 ±ENV_SINE_W (0.05C) 再 ±ΔP 压移:
    // 上下边界本身也是正弦形, 沿整条曲线等宽包裹标称 (非三角近似)。
    // 时移在峰/谷被钳到极值 → 峰/谷平段 0.1C (最大驻留); 峰/谷垂直
    // 容差 ±ΔP (标准 0.02·PMax); PMean (斜率最大) 处水平带宽 = 2·W
    // = 0.1C (最大畸变)。时移恒向极值方向 → 标称必在带内, 无需钳位。
    rEnvDP := rEnvPctP;
    IF rEnvDP <= 0.0 THEN rEnvDP := ENV_SINE_DP; END_IF
    rEnvDP := rEnvDP * rPMax;

    // 上包络: 标称正弦相位向峰 (0.5) 超前 W, 钳在峰; 整条 +ΔP
    IF rPhase <= 0.5 THEN
        rEnvPhU := rPhase + ENV_SINE_W;
        IF rEnvPhU > 0.5 THEN rEnvPhU := 0.5; END_IF
    ELSE
        rEnvPhU := rPhase - ENV_SINE_W;
        IF rEnvPhU < 0.5 THEN rEnvPhU := 0.5; END_IF
    END_IF
    rTargetUpper := FN_PulseWave(
        rPhaseIn := rEnvPhU, rPMin := rPMin, rPMax := rPMax, iWaveType := 0,
        rR := 0.0, rH := 0.0, rF := 0.0, rRing := 0.0, rPeakOS := rPMax) + rEnvDP;

    // 下包络: 标称正弦相位向谷 (0/1) 滞后 W, 钳在谷; 整条 -ΔP
    IF rPhase <= 0.5 THEN
        rEnvPhL := rPhase - ENV_SINE_W;
        IF rEnvPhL < 0.0 THEN rEnvPhL := 0.0; END_IF
    ELSE
        rEnvPhL := rPhase + ENV_SINE_W;
        IF rEnvPhL > 1.0 THEN rEnvPhL := 1.0; END_IF
    END_IF
    rTargetLower := FN_PulseWave(
        rPhaseIn := rEnvPhL, rPMin := rPMin, rPMax := rPMax, iWaveType := 0,
        rR := 0.0, rH := 0.0, rF := 0.0, rRing := 0.0, rPeakOS := rPMax) - rEnvDP;
END_CASE

IF rTargetLower < 0.0 THEN rTargetLower := 0.0; END_IF
IF rTargetUpper > 50.0 THEN rTargetUpper := 50.0; END_IF


// ============================================================
// 首次运行初始化 (避免起步瞬间 dP/dt 出现伪大值)
// ============================================================
IF bFirstRun THEN
    rTargetPrev := rTarget;
    rTargetLeadPrev := rTargetLead;
    bFirstRun := FALSE;
END_IF

rTargetLast := rTarget;
rTargetLeadLast := rTargetLead;

iIdxCounter := iIdxCounter + 1;

// ============================================================
// 每周期首先执行数据打包（PLC→PC）
// 这是最先执行的步骤：将 PLC 当前所有需要上传的状态、数据
// 写入 INPUT_REGISTER 缓冲区，为后续 TCP_Write 发送做准备。
// 必须在 TCP_Write 之前调用，否则发送的是上一周期的旧数据。
// ============================================================
TCP_PLC_to_PC();
(*
// ============================================================
// 初始化：动态计算 FOR 循环上界
// mark_for_mun = SIZEOF(write_mark_bool) - 1
// 仅在首次执行时计算一次，后续周期不再重复计算（因为数组大小固定）
// ============================================================
IF initial_run THEN
    mark_for_mun := SIZEOF(write_mark_bool) - 1;
END_IF

// ============================================================
// 服务器异常后 FT 自动重启使能
// 容错重启机制：
//   当 TCP_Server_open 出现错误（xError=TRUE）或句柄丢失（hServer=0）时，
//   blink_server 开始闪烁 server_en（反复 FALSE/TRUE），产生上升沿触发重新打开服务器。
//   当服务器恢复正常（xError=FALSE 且 hServer≠0）时，server_en 保持 TRUE，闪烁停止。
// ============================================================
IF TCP_Server_open.xError OR (TCP_Server_open.hServer = 0) THEN
    blink_server(i_enable := TRUE, out_bool => server_en);
ELSE
    server_en := TRUE;
    blink_server(i_enable := FALSE);
END_IF

// ============================================================
// 启动/重启 TCP Server
// 服务器生命周期第一步：open（打开套接字）
//   - xEnable 上升沿触发：绑定 IP_ADR_server + ServerPORT，开始监听
//   - 输出 xBusy=TRUE 表示正在监听，hServer 为服务器句柄（供 TCP_Connection 使用）
//   - 输出 xDone=TRUE 表示服务器已关闭（xEnable 下降沿时）
//   - 输出 xError=TRUE 表示打开失败
// 当 connectNG（连接丢失）或首次运行时，重新调用以确保服务器处于监听状态
// ============================================================
IF connectNG OR initial_run THEN
    cishuhaha := cishuhaha + 1;
    TCP_Server_open(
        xEnable  := server_en,
        ipAddr   := IP_ADR_server,
        uiPort   := ServerPORT,
        xDone    => ,
        xBusy    => ,
        xError   => ,
        eError   => ,
        hServer  => );
END_IF

// ============================================================
// 检测客户端连接
// 服务器生命周期第二步：accept（接受客户端连接）
//   - xEnable 持续为 TRUE 时，TCP_Connection 等待客户端连接
//   - hServer 由 TCP_Server_open 提供，标识在哪个服务器上等待连接
//   - 连接成功后 xActive=TRUE，hConnection 为连接句柄（供 Read/Write 使用）
//   - xError=TRUE 表示连接失败
//   re_connection 检测连接丢失的上升沿（connectNG 从 FALSE→TRUE），
//   短暂禁用 TCP_Connection 以触发重新等待连接
// ============================================================
connectNG := (TCP_Connection.hConnection = 0);
re_connection(CLK := connectNG);

TCP_Connection(
    xEnable     := TCP_Server_open.xBusy AND NOT re_connection.Q,
    hServer     := TCP_Server_open.hServer,
    xDone       => ,
    xBusy       => ,
    xError      => ,
    eError      => ,
    xActive     => ,
    hConnection => );

// ============================================================
// READ：接收上位机数据 → HOLDING_REGISTER
// 服务器生命周期第三步：read（读取数据）
//   - xEnable 持续为 TRUE 时，每周期尝试从已建立的连接中读取数据
//   - hConnection 由 TCP_Connection 提供
//   - szSize 指定读取长度 = HOLDING_REGISTER 的大小
//   - pData 指向 HOLDING_REGISTER 的地址，数据直接写入该缓冲区
//   - xReady=TRUE 表示有新数据到达（可在此触发解析）
//   - xDone=TRUE 表示读取完成
//   - 读取到的数据将由最后的 TCP_PC_to_PLC() 进行解析
// ============================================================
server_read(
    xEnable     := TCP_Connection.xActive,
    hConnection := TCP_Connection.hConnection,
    szSize      := SIZEOF(TCP_PC_to_PLC.HOLDING_REGISTER),
    pData       := ADR(TCP_PC_to_PLC.HOLDING_REGISTER),
    xDone       => ,
    xBusy       => ,
    xError      => ,
    eError      => ,
    xReady      => ,
    szCount     => );

// ============================================================
// WRITE：发送 INPUT_REGISTER → 上位机（每周期写一次，交替触发）
// 服务器生命周期第四步：write（写入数据）
//   使用 FOR 循环 + write_mark_bool 交替触发方案：
//   - i_for=0: write_mark_bool[0]=FALSE → xExecute=FALSE（下降沿，为下次上升沿做准备）
//   - i_for=1: write_mark_bool[1]=TRUE  → xExecute=TRUE（上升沿，触发本次发送）
//   每个扫描周期内，同一个 server_write 功能块被调用两次：
//     第一次(FALSE)复位内部状态，第二次(TRUE)产生上升沿触发发送。
//   这是因为 NBS.TCP_Write 的 xExecute 需要上升沿触发，
//   如果 xExecute 始终为 TRUE 则只会发送一次，不会持续发送。
//   交替触发确保每个 10ms 周期都能成功发送一帧数据。
//   发送的数据是 INPUT_REGISTER，由 TCP_PLC_to_PC() 在周期开始时打包完毕。
// ============================================================
FOR i_for := 0 TO mark_for_mun DO
    server_write(
        xExecute    := TCP_Connection.xActive AND write_mark_bool[i_for],
        udiTimeOut  := 3008,
        hConnection := TCP_Connection.hConnection,
        szSize      := SIZEOF(TCP_PLC_to_PC.INPUT_REGISTER),
        pData       := ADR(TCP_PLC_to_PC.INPUT_REGISTER),
        xDone       => write_done_bool[i_for],
        xBusy       => write_busy_bool[i_for],
        xError      => write_error_bool[i_for],
        eError      => );
END_FOR


// ============================================================
// 结束初始化标志
// ============================================================
IF initial_run THEN
    initial_run := FALSE;
END_IF

// ============================================================
// 解析上位机数据（PC→PLC）
// 这是最后执行的步骤：从 HOLDING_REGISTER 中提取上位机下发的
// 各项参数（如设定值、命令等），写入对应的 PLC 变量。
// 必须在 TCP_Read 之后调用，因为此时 HOLDING_REGISTER 中才有最新接收的数据。
// 执行顺序总结：打包(TCP_PLC_to_PC) → 发送(TCP_Write) → 接收(TCP_Read) → 解析(TCP_PC_to_PLC)
// ============================================================

*)
// ============================================================
// 10 ms 帧计数递增（PLC→PC 帧计数器）
// FrameTick 每周期 +1，写入 PP_FrameCounter_PLC，
// 上位机可通过此值判断 PLC 是否在正常运行和通讯
// ============================================================
FrameTick := FrameTick + 1;
GVL_PulsePressure.PP_FrameCounter_PLC := DINT_TO_REAL(FrameTick);

TCP_PC_to_PLC();

{*
26.01为剂侧产品端低压力传感器
27.01为剂侧产品端15MPa高压力传感器
*}

//剂侧产品端压力 — 默认使用26.01低压传感器(可根据需要切换27.01)
PP_Oil_ActualPressure := GVL_PulsePressure.PP_Dev_Pressure_26_01;

// 滤波时间常数从 GVL 取, 带范围保护 (默认 100ms; ≤1ms 视为旁路, ≥10s 限幅)
rOilFilterTauMs := GVL_PulsePressure.PP_Oil_Filter;
IF rOilFilterTauMs < 1.0     THEN rOilFilterTauMs := 1.0;     END_IF
IF rOilFilterTauMs > 10000.0 THEN rOilFilterTauMs := 10000.0; END_IF
tOilFilterTau := DWORD_TO_TIME(REAL_TO_DWORD(rOilFilterTauMs));

Oil_Pressure_Filter(in:= PP_Oil_ActualPressure, t:= tOilFilterTau);
GVL_PulsePressure.PP_Oil_ActualPressure := Oil_Pressure_Filter.out;

// ============================================================
// 1ms 分辨率压力缓冲 (供上位机以 10ms 通讯周期读取 10 个采样)
// ------------------------------------------------------------
// 本 PRG 在 1ms 任务里跑, 每周期向本地写缓冲追加一个采样;
// 累满 10 个 (即一个完整的 10ms 窗口) 后整体复制到 GVL 数组,
// 上位机 TCP 任务在 10ms 节拍上读到的是上一个窗口的完整 10 点序列, 无撕裂。
// 索引语义: rPress1msBuf_O[0] 是窗口起点 (t-9ms), [9] 是窗口终点 (t-0ms, 最新)
// ============================================================
rPress1msBuf_O[nMs1msIdx] := GVL_PulsePressure.PP_Oil_ActualPressure;
IF nMs1msIdx >= 9 THEN
    GVL_PulsePressure.PP_Oil_ActualPressure_1ms := rPress1msBuf_O;  // 整体快照
    nMs1msIdx := 0;
ELSE
    nMs1msIdx := nMs1msIdx + 1;
END_IF


//方向系数
PWMotion.FPGAData.Axis1.OutputCoefficient := 1;


// ============================================================
// 循环计数清零（上升沿检测，任何状态下都执行）
// PC写入CycleReset=1.0触发清零，清零后PC应写回0.0
// ============================================================
IF GVL_PulsePressure.PP_Oil_CycleReset = 1.0 AND NOT bOilCycleResetPrev THEN
    GVL_PulsePressure.PP_Oil_CyclesDone := 0.0;
    GVL_PulsePressure.PP_TotalCyclesDone := 0.0;
END_IF
bOilCycleResetPrev := (GVL_PulsePressure.PP_Oil_CycleReset = 1.0);

// ============================================================
// PC命令解析
// PP_SysCommand: 0=空闲 1=冲洗排气 2=运行 3=停止
// 命令变化时触发状态切换
// ============================================================
iCmd := REAL_TO_INT(GVL_PulsePressure.PP_SysCommand);
bCmdChanged := (iCmd <> iCmdPrev);
iCmdPrev := iCmd;

// 命令变化时执行状态切换
IF bCmdChanged THEN
    // 进入冲洗或运行前复位所有控制器 (原 InitializeControllers 方法)
    // - fbWaveGen_O 清相位累加器、计数器
    // - fbPID_O 清积分、微分
    // - fbILC_O 清学习历史
    IF iCmd = 1 OR iCmd = 2 THEN
        fbWaveGen_O(bReset := TRUE);
        fbPID_O(bReset := TRUE);
        fbILC_O(bReset := TRUE);
        rPeakPressure_O := 0.0;
        rStopRampVal_O := GVL_PulsePressure.PP_Oil_ActualPressure;
    END_IF

    CASE iCmd OF
        0: // 回空闲
            iState := 0;
        1: // 冲洗排气
            rFlushDuration := GVL_PulsePressure.PP_FlushDuration;
            rFlushOutput := GVL_PulsePressure.PP_FlushValveOutput;
            IF rFlushOutput < 0.5 THEN rFlushOutput := 2.0; END_IF
            IF rFlushOutput > 5.0 THEN rFlushOutput := 5.0; END_IF
            rFlushTimer := 0.0;
            iState := 1;
        2: // 运行（伺服阀直接控制压力，无需油缸到位检查/预加压）
		    rFlushTimer := 0.0;
            iState := 3;
        3: // 停止
            rStopRampVal_O := GVL_PulsePressure.PP_Oil_ActualPressure;
            iState := 4;
    END_CASE
    GVL_PulsePressure.PP_StateReady := 0.0;
END_IF

// ============================================================
// 通道选择（只有油路）
// 始终走剂侧测试: 油路通断阀 10.01/10.03 打开
// 实际硬件驱动由 PRG_DeviceControl（待重写）从 GVL_GPIO 直接读取
// ============================================================



// ============================================================
// 计算实际PMin（直接使用上位机设定值，0即为0MPa）
// ============================================================
rActualPMin_O := GVL_PulsePressure.PP_Oil_MinPressure;
IF rActualPMin_O < 0.0 THEN rActualPMin_O := 0.0; END_IF
IF rActualPMin_O >= GVL_PulsePressure.PP_Oil_TargetPressure THEN
    rActualPMin_O := GVL_PulsePressure.PP_Oil_TargetPressure * 0.9;
END_IF

// ============================================================
// 状态机
// ============================================================
CASE iState OF

// ------------------------------------------------------------
// 状态0: 空闲
// 所有控制输出清零，等待PC写入新命令
// ------------------------------------------------------------
0:
    bRunning := FALSE;
    rUTotal_O := 0.0;
    GVL_PulsePressure.PP_SysState := 0.0;  // 空闲
    GVL_PulsePressure.PP_FlushTimeRemaining := 0.0;
    GVL_PulsePressure.PP_StateReady := 0.0;

// ------------------------------------------------------------
// 状态1: 冲洗排气 — 低压循环排出管路中的空气
// PLC置StateReady=1通知PC冲洗完成，由PC决定何时发下一命令。
// ------------------------------------------------------------
1:
    bRunning := TRUE;
    GVL_PulsePressure.PP_SysState := 1.0;  // 冲洗排气

    // 冲洗计时
    rFlushTimer := rFlushTimer + rDt;
    GVL_PulsePressure.PP_FlushTimeRemaining := rFlushDuration - rFlushTimer;
    IF GVL_PulsePressure.PP_FlushTimeRemaining < 0.0 THEN
        GVL_PulsePressure.PP_FlushTimeRemaining := 0.0;
    END_IF

    // 直接伺服阀控制系统: 冲洗排气期间阀口保持小开度排气, 不做油缸往复
    PWMOTION.FPGAData.Axis1.Output_ManualSet := rFlushOutput * 10;

    // 冲洗时间到 → 置就绪标志，通知 PC 发下一命令
    IF rFlushTimer >= rFlushDuration THEN
        GVL_PulsePressure.PP_FlushTimeRemaining := 0.0;
        GVL_PulsePressure.PP_StateReady := 1.0;
    END_IF
// ------------------------------------------------------------
// 状态3: 运行 — MFF + ILC + PID 复合控制
// 此状态下执行完整的6步控制流水线:
//   1) 波形生成 → 2) 计算跟踪误差 → 3) MFF前馈
//   → 4) ILC前馈 → 5) PID反馈 → 6) 三路叠加
// ============================================================
3:
    bRunning := TRUE;
    GVL_PulsePressure.PP_SysState := 3.0;  // 运行

    // ==================== 油路控制 (ILC 修指令 + PID 反馈) ====================

    // ---- 1. 波形生成 (含 ARP1383C 误差包络) ----
    fbWaveGen_O(
        bEnable       := TRUE,
        rPMin         := rActualPMin_O,
        rPMax         := GVL_PulsePressure.PP_Oil_TargetPressure,
        rFrequency    := GVL_PulsePressure.PP_Oil_Frequency,
        iWaveType     := REAL_TO_INT(GVL_PulsePressure.PP_Oil_WaveType),
        rRisePct      := GVL_PulsePressure.PP_Oil_RisePct,
        rHoldPct      := GVL_PulsePressure.PP_Oil_HoldPct,
        rFallPct      := GVL_PulsePressure.PP_Oil_FallPct,
        rOvershoot    := GVL_PulsePressure.PP_Oil_Overshoot,
        rRingPct      := GVL_PulsePressure.PP_Oil_RingPct,
        rLowDwellPct  := GVL_PulsePressure.PP_Oil_LowDwellPct,
        rRiseRate     := GVL_PulsePressure.PP_Oil_WHRiseRate,
        rDt           := rDt,
        bReset        := FALSE,
        nMffLeadSteps := 0,    // 已移除 MFF, 不再需要超前相位
        rEnvPctP      := GVL_PulsePressure.PP_Oil_EnvPctP
    );

    GVL_PulsePressure.PP_Oil_SetpointPressure := fbWaveGen_O.rTarget;

    // ============================================================
    // ARP1383C 显示包络相位对齐 (仅显示, 不影响 ILC)
    // 实际压力相对指令有稳态滞后; 若把命令相位包络直接送 HMI, "形状/
    // 幅值合格但有滞后"的实际曲线会在边沿被画成越界。这里用整周期互
    // 相关在线估 actual 相对指令的滞后, 把命令相位包络在时间上延迟同
    // 样的量后送 HMI, 使容差带套住实际曲线。ILC 仍用命令相位包络
    // (fbWaveGen_O.rTargetUpper/Lower, 见下方调用), 继续主动消除滞后,
    // 控制行为不变。
    // 算法: 每周期把 actual / 指令按相位分箱 (ENV_NCORR 箱); 周期边界
    //       对两条均值曲线做去均值互相关, 取相关最大的整数滞后 kbest
    //       → 滞后占比 kbest/ENV_NCORR, 逐周期指数平滑; 显示包络 = 命令
    //       相位包络环形缓冲中延迟 round(lag·N) 个采样的值。
    // ============================================================
    iEnvN_O   := fbWaveGen_O.iPointsPerCycle;
    iEnvIdx_O := fbWaveGen_O.iPointIndex;

    IF fbWaveGen_O.bNewCycle THEN
        IF (iEnvN_O >= ENV_NCORR) AND (iEnvN_O <= ENV_MAXPPC) THEN
            // 分箱取均值 + 总体均值 (去均值用)
            rEnvMeanA_O := 0.0;
            rEnvMeanC_O := 0.0;
            FOR iEnvB_O := 0 TO ENV_NCORR - 1 DO
                IF iEnvBinCnt_O[iEnvB_O] > 0 THEN
                    rEnvActBin_O[iEnvB_O] := rEnvActBin_O[iEnvB_O] / INT_TO_REAL(iEnvBinCnt_O[iEnvB_O]);
                    rEnvCmdBin_O[iEnvB_O] := rEnvCmdBin_O[iEnvB_O] / INT_TO_REAL(iEnvBinCnt_O[iEnvB_O]);
                END_IF
                rEnvMeanA_O := rEnvMeanA_O + rEnvActBin_O[iEnvB_O];
                rEnvMeanC_O := rEnvMeanC_O + rEnvCmdBin_O[iEnvB_O];
            END_FOR
            rEnvMeanA_O := rEnvMeanA_O / INT_TO_REAL(ENV_NCORR);
            rEnvMeanC_O := rEnvMeanC_O / INT_TO_REAL(ENV_NCORR);

            // 去均值互相关, 搜索 k = 0..ENV_KMAX (actual 滞后 ⇒ 命令回移 k 对齐)
            iEnvBestK_O    := 0;
            rEnvBestCorr_O := -1.0E30;
            FOR iEnvK_O := 0 TO ENV_KMAX DO
                rEnvCorr_O := 0.0;
                FOR iEnvB_O := 0 TO ENV_NCORR - 1 DO
                    iEnvRd_O := iEnvB_O - iEnvK_O;
                    IF iEnvRd_O < 0 THEN iEnvRd_O := iEnvRd_O + ENV_NCORR; END_IF
                    rEnvCorr_O := rEnvCorr_O
                        + (rEnvActBin_O[iEnvB_O] - rEnvMeanA_O)
                        * (rEnvCmdBin_O[iEnvRd_O] - rEnvMeanC_O);
                END_FOR
                IF rEnvCorr_O > rEnvBestCorr_O THEN
                    rEnvBestCorr_O := rEnvCorr_O;
                    iEnvBestK_O    := iEnvK_O;
                END_IF
            END_FOR

            rEnvLagNew_O := INT_TO_REAL(iEnvBestK_O) / INT_TO_REAL(ENV_NCORR);
            rEnvLag_O    := rEnvLag_O + ENV_LAGSMOOTH * (rEnvLagNew_O - rEnvLag_O);
            iEnvKDelay_O := REAL_TO_INT(rEnvLag_O * INT_TO_REAL(iEnvN_O));
            IF iEnvKDelay_O < 0 THEN iEnvKDelay_O := 0; END_IF
            IF iEnvKDelay_O > iEnvN_O - 1 THEN iEnvKDelay_O := iEnvN_O - 1; END_IF
        ELSE
            rEnvLag_O    := 0.0;   // N 超范围: 退化为命令相位包络
            iEnvKDelay_O := 0;
        END_IF
        // 清空分箱, 开始累计新周期
        FOR iEnvB_O := 0 TO ENV_NCORR - 1 DO
            rEnvActBin_O[iEnvB_O] := 0.0;
            rEnvCmdBin_O[iEnvB_O] := 0.0;
            iEnvBinCnt_O[iEnvB_O] := 0;
        END_FOR
    END_IF

    // 本采样: 写命令相位包络环形缓冲 + 按相位分箱累加 actual/指令; 输出延迟后的显示包络
    IF (iEnvN_O >= ENV_NCORR) AND (iEnvN_O <= ENV_MAXPPC)
       AND (iEnvIdx_O >= 0) AND (iEnvIdx_O < iEnvN_O) THEN
        rEnvUpBuf_O[iEnvIdx_O] := fbWaveGen_O.rTargetUpper;
        rEnvLoBuf_O[iEnvIdx_O] := fbWaveGen_O.rTargetLower;
        iEnvBin_O := REAL_TO_INT(INT_TO_REAL(iEnvIdx_O) * INT_TO_REAL(ENV_NCORR) / INT_TO_REAL(iEnvN_O) - 0.5);
        IF iEnvBin_O < 0 THEN iEnvBin_O := 0; END_IF
        IF iEnvBin_O > ENV_NCORR - 1 THEN iEnvBin_O := ENV_NCORR - 1; END_IF
        rEnvActBin_O[iEnvBin_O] := rEnvActBin_O[iEnvBin_O] + GVL_PulsePressure.PP_Oil_ActualPressure;
        rEnvCmdBin_O[iEnvBin_O] := rEnvCmdBin_O[iEnvBin_O] + fbWaveGen_O.rTarget;
        iEnvBinCnt_O[iEnvBin_O] := iEnvBinCnt_O[iEnvBin_O] + 1;

        iEnvRd_O := iEnvIdx_O - iEnvKDelay_O;
        IF iEnvRd_O < 0 THEN iEnvRd_O := iEnvRd_O + iEnvN_O; END_IF
        GVL_PulsePressure.PP_Oil_TargetUpper := rEnvUpBuf_O[iEnvRd_O];
        GVL_PulsePressure.PP_Oil_TargetLower := rEnvLoBuf_O[iEnvRd_O];
    ELSE
        GVL_PulsePressure.PP_Oil_TargetUpper := fbWaveGen_O.rTargetUpper;
        GVL_PulsePressure.PP_Oil_TargetLower := fbWaveGen_O.rTargetLower;
    END_IF

    GVL_PulsePressure.PP_Oil_EnvPhaseLag  := rEnvLag_O * 100.0;  // actual 滞后 (周期 %), 仅显示遥测

    GVL_PulsePressure.PP_Oil_WavePhase    := fbWaveGen_O.rPhase * 360.0;
    GVL_PulsePressure.PP_Oil_Frequency_FB := GVL_PulsePressure.PP_Oil_Frequency;

    // 周期计数 + 峰值锁存
    IF fbWaveGen_O.bNewCycle THEN
        GVL_PulsePressure.PP_Oil_CyclesDone   := GVL_PulsePressure.PP_Oil_CyclesDone + 1.0;
        GVL_PulsePressure.PP_TotalCyclesDone  := GVL_PulsePressure.PP_TotalCyclesDone + 1.0;
        GVL_PulsePressure.PP_Oil_PeakPressure := rPeakPressure_O;
        rPeakPressure_O := 0.0;
    END_IF
    IF GVL_PulsePressure.PP_Oil_ActualPressure > rPeakPressure_O THEN
        rPeakPressure_O := GVL_PulsePressure.PP_Oil_ActualPressure;
    END_IF

    // ---- 2. ILC 指令修正 (MPa 域) ----
    // 新架构: ILC 不再作为电压前馈分量, 而是学习对目标指令本身的修正量,
    // 然后 PID 跟踪修正后的目标. 这样:
    //   - 单位一致: rOutput 是 MPa 级修正, 加到 rTarget (MPa) 上
    //   - 物理意义清晰: 学到的是 "为了让实际压力达到 rTarget, 阀控制器应该追的虚拟目标"
    //   - 闭环稳定性由 PID 单独保证, ILC 只是循环间慢学习
    // nWaveType 与 FB_WaveformGen 同编码: 0=正弦 / 1=梯形 / 2=水锤波
    // 段宽来自 fbWaveGen_O 已归一化的 rSegRise / rSegRing / rSegHold / rSegFall
    fbILC_O(
        bEnable         := (GVL_PulsePressure.PP_Oil_ILC_Enable >= 0.5),
        rTargetRaw      := fbWaveGen_O.rTarget,
        rActual         := GVL_PulsePressure.PP_Oil_ActualPressure,
        iPointIndex     := fbWaveGen_O.iPointIndex,
        iPointsPerCycle := fbWaveGen_O.iPointsPerCycle,
        bNewCycle       := fbWaveGen_O.bNewCycle,
        bReset          := FALSE,
        iMaxIterations  := REAL_TO_INT(GVL_PulsePressure.PP_Oil_ILC_MaxIter),
        rLearningRate   := GVL_PulsePressure.PP_Oil_ILC_LearningRate,
        bTrapShapeEnable := (GVL_PulsePressure.PP_Oil_ILC_TrapShape >= 0.5),  // 梯形: 默认仅端点补偿; ≥0.5 才开形态补偿
        iWaveTypeIn     := REAL_TO_INT(GVL_PulsePressure.PP_Oil_WaveType),
        rWHPMaxTarget   := GVL_PulsePressure.PP_Oil_TargetPressure,
        rWHRiseFrac     := fbWaveGen_O.rSegRise,
        rWHRingFrac     := fbWaveGen_O.rSegRing,
        rWHHoldFrac     := fbWaveGen_O.rSegHold,
        rWHFallFrac     := fbWaveGen_O.rSegFall,
        rEnvUpper       := fbWaveGen_O.rTargetUpper,  // ARP1383C 包络: 在包络内停学习, 越界才学习
        rEnvLower       := fbWaveGen_O.rTargetLower
    );
    rIlcCorrection_O := fbILC_O.rOutput;                                 // MPa
    rTargetCorrected_O := fbWaveGen_O.rTarget + rIlcCorrection_O;        // MPa
    GVL_PulsePressure.PP_Oil_ILC_Output    := rIlcCorrection_O;
    GVL_PulsePressure.PP_Oil_ILC_Iteration := INT_TO_REAL(fbILC_O.iIteration);

    // ---- 3. 跟踪误差 (基于 ILC 修正后的目标) ----
    rError_O := rTargetCorrected_O - GVL_PulsePressure.PP_Oil_ActualPressure;
    GVL_PulsePressure.PP_Oil_PressureError := rError_O;

    // ---- 4. PID 反馈 ----
    fbPID_O(
        bEnable := TRUE,
        rError  := rError_O,
        rDt     := rDt,
        bReset  := FALSE,
        rPID_Kp := GVL_PulsePressure.PP_Oil_PID_Kp,
        rPID_Ki := GVL_PulsePressure.PP_Oil_PID_Ki,
        rPID_Kd := GVL_PulsePressure.PP_Oil_PID_Kd
    );
    rUPid_O := fbPID_O.rOutput;
    GVL_PulsePressure.PP_Oil_PID_Output   := rUPid_O;
    GVL_PulsePressure.PP_Oil_PID_Integral := fbPID_O.rPID_I;

    // ---- 5. 阀控电压 = PID 输出 (无 MFF 前馈) ----
    rUTotal_O := rUPid_O;
    IF rUTotal_O >  10.0 THEN rUTotal_O :=  10.0; END_IF
    IF rUTotal_O < -10.0 THEN rUTotal_O := -10.0; END_IF

    PWMOTION.FPGAData.Axis1.Output_ManualSet := rUTotal_O * 10;

    // 检查目标循环数（到达后自动停止）
    IF GVL_PulsePressure.PP_Oil_TargetCycles > 0.0 THEN
        IF GVL_PulsePressure.PP_Oil_CyclesDone >= GVL_PulsePressure.PP_Oil_TargetCycles THEN
            rStopRampVal_O := GVL_PulsePressure.PP_Oil_ActualPressure;
            iState := 4;
        END_IF
    END_IF

// ------------------------------------------------------------
// 状态4: 停止中 — 缓慢卸压
// 停止斜坡机制说明:
//   进入状态4时 (命令 3) rStopRampVal_O 已在 CASE iCmd 中被初始化为当前实际压力。
//   每个控制周期(1ms)按 rStopRampRate=5MPa/s 递减目标值，
//   并用比例控制(rStopRampKp=2.0)跟踪递减目标值。
//   这实现了从当前压力到零的平滑下降，避免直接关闭阀门导致的
//   水锤效应或压力冲击。当实际压力降到0.5MPa以下时认为卸压完成，
//   返回空闲状态(状态0)。
// ------------------------------------------------------------
4:
    GVL_PulsePressure.PP_SysState := 4.0;  // 停止中

    // 油路卸压
    IF GVL_PulsePressure.PP_Oil_ActualPressure > 0.5 THEN
        // 斜坡目标值每ms递减 rStopRampRate*0.001 = 0.005MPa
        // 即5MPa/s的卸压速率
        rStopRampVal_O := rStopRampVal_O - rStopRampRate * rDt;
        IF rStopRampVal_O < 0.0 THEN rStopRampVal_O := 0.0; END_IF
        rStopRampErr_O := rStopRampVal_O - GVL_PulsePressure.PP_Oil_ActualPressure;
        PWMOTION.FPGAData.Axis1.Output_ManualSet := rUTotal_O := rStopRampKp * rStopRampErr_O;
    ELSE
        PWMOTION.FPGAData.Axis1.Output_ManualSet := rUTotal_O := 0.0;
    END_IF

    // 卸压完成 → 置就绪标志，通知PC（PC发命令0回空闲）
    IF GVL_PulsePressure.PP_Oil_ActualPressure < 0.5 THEN
        GVL_PulsePressure.PP_StateReady := 1.0;
    END_IF

// ------------------------------------------------------------
// 状态5: 故障
// 由高压保护触发，所有输出强制清零
// PC发命令0即可恢复到空闲状态
// ------------------------------------------------------------
5:
    rUTotal_O := 0.0;
    PWMOTION.FPGAData.Axis1.Output_ManualSet := 0;
    GVL_PulsePressure.PP_SysState := 5.0;  // 故障

END_CASE

// ============================================================
// 高压保护 — 任何状态下都执行，优先级高于状态机
// 说明: 当实际压力超过设定的限值(HighLimit)时，
//   1) 强制控制输出为0V，并打开回油阀快速泄压
//   2) 立即将状态机切换到故障状态(状态5)
//   此保护在CASE语句之后执行，因此会覆盖任何状态下的控制输出，
//   确保即使运行状态中出现超压也能立即响应。
//   高压保护条件: HighLimit > 0 且 实际压力 > HighLimit
//   HighLimit > 0的检查是为了防止未设定限值时误触发
// ============================================================
IF GVL_PulsePressure.PP_Oil_ActualPressure > GVL_PulsePressure.PP_Oil_HighLimit
   AND GVL_PulsePressure.PP_Oil_HighLimit > 0.0 THEN
    PWMOTION.FPGAData.Axis1.Output_ManualSet := rUTotal_O := 0.0;
	GVL_PulsePressure.PP_Dev_PneValve_YV7 := 1.0;  // 待 PRG_DeviceControl 驱动 YV7 硬件
    iState := 5;
ELSE
	GVL_PulsePressure.PP_Dev_PneValve_YV7 := 0.0;
END_IF

// ============================================================
// 急停保护 — 任何状态下都执行
// 急停时强制切到停止状态(状态4)进行斜坡卸压
// ============================================================
IF GVL_PulsePressure.PP_EmergencyStop = 1.0 AND iState <> 0 AND iState <> 4 AND iState <> 5 THEN
    rStopRampVal_O := GVL_PulsePressure.PP_Oil_ActualPressure;
    iState := 4;
END_IF

// ============================================================
// 输出到全局变量
// ============================================================
// 总控制输出限幅: ±10V 对应伺服阀最大驱动范围
IF rUTotal_O > 10.0 THEN rUTotal_O := 10.0; END_IF
IF rUTotal_O < -10.0 THEN rUTotal_O := -10.0; END_IF

GVL_PulsePressure.PP_Oil_ControlOutput := rUTotal_O;

// ===================================================================
// TCP HOLDING_REGISTER 地址布局 (PC → PLC, V5.0)
// ===================================================================
// 设计原则:
//   - 每节内字段从基址连续紧排, 节尾留大块预留
//   - 节边界对齐 32W 倍数, 便于上位机分块读写
//   - 字段一旦发布不再挪位; 新字段从节末预留区追加
// ===================================================================
// [A] 系统控制    0   – 31    (32 W;  6 字段 = 12 W, 余 20 W)
// [B] 冲洗排气    32  – 47    (16 W;  2 字段 =  4 W, 余 12 W)
// [C] 油路波形    48  – 95    (48 W; 15 字段 = 30 W, 余 18 W)
// [D] 控制器      96  – 127   (32 W;  7 字段 = 14 W, 余 18 W)  ILC + PID + 滤波
// [E] 液压站     128 – 159    (32 W;  4 字段 =  8 W, 余 24 W)
// [F] IO 控制    160 – 191    (32 W;  2 字段 =  4 W, 余 28 W)
// [G] 设备控制   192 – 255    (64 W; 由 PRG_DeviceControl 解析)
// [Z] 未来扩展   256 – 1999
// ===================================================================


// ===== [A] 系统控制 (0-31) =====
i := 0;

TwoWord_to_Float(word_low := HOLDING_REGISTER[i], word_high := HOLDING_REGISTER[i+1]);
GVL_PulsePressure.PP_FrameCounter_PC := TwoWord_to_Float.Output;        // 0-1: 上位机帧计数器(心跳)
i := i + 2;

TwoWord_to_Float(word_low := HOLDING_REGISTER[i], word_high := HOLDING_REGISTER[i+1]);
GVL_PulsePressure.PP_SysCommand := TwoWord_to_Float.Output;             // 2-3: 系统命令 0=空闲 1=冲洗 2=运行 3=停止
i := i + 2;

TwoWord_to_Float(word_low := HOLDING_REGISTER[i], word_high := HOLDING_REGISTER[i+1]);
GVL_PulsePressure.PP_AlarmReset := TwoWord_to_Float.Output;             // 4-5: 报警复位
i := i + 2;

TwoWord_to_Float(word_low := HOLDING_REGISTER[i], word_high := HOLDING_REGISTER[i+1]);
GVL_PulsePressure.PP_Enable := TwoWord_to_Float.Output;                 // 6-7: 系统使能
i := i + 2;

TwoWord_to_Float(word_low := HOLDING_REGISTER[i], word_high := HOLDING_REGISTER[i+1]);
GVL_PulsePressure.PP_EmergencyStop := TwoWord_to_Float.Output;          // 8-9: 急停
i := i + 2;

TwoWord_to_Float(word_low := HOLDING_REGISTER[i], word_high := HOLDING_REGISTER[i+1]);
GVL_PulsePressure.PP_HeartbeatTimeout := TwoWord_to_Float.Output;       // 10-11: 心跳超时(s)
i := i + 2;

// 12-31: 保留 (10 字段)


// ===== [B] 冲洗排气 (32-47) =====
i := 32;

TwoWord_to_Float(word_low := HOLDING_REGISTER[i], word_high := HOLDING_REGISTER[i+1]);
GVL_PulsePressure.PP_FlushDuration := TwoWord_to_Float.Output;          // 32-33: 冲洗持续时间(s); 0=跳过冲洗
i := i + 2;

TwoWord_to_Float(word_low := HOLDING_REGISTER[i], word_high := HOLDING_REGISTER[i+1]);
GVL_PulsePressure.PP_FlushValveOutput := TwoWord_to_Float.Output;       // 34-35: 冲洗阀门输出(V); 默认 2.0
i := i + 2;

// 36-47: 保留 (6 字段)


// ===== [C] 油路波形 (48-95) =====
i := 48;

TwoWord_to_Float(word_low := HOLDING_REGISTER[i], word_high := HOLDING_REGISTER[i+1]);
GVL_PulsePressure.PP_Oil_WaveType := TwoWord_to_Float.Output;           // 48-49: 波形类型 0=正弦 1=梯形 2=ARP1383 水锤
i := i + 2;

TwoWord_to_Float(word_low := HOLDING_REGISTER[i], word_high := HOLDING_REGISTER[i+1]);
GVL_PulsePressure.PP_Oil_TargetPressure := TwoWord_to_Float.Output;     // 50-51: 目标峰值压力 PMax (MPa)
i := i + 2;

TwoWord_to_Float(word_low := HOLDING_REGISTER[i], word_high := HOLDING_REGISTER[i+1]);
GVL_PulsePressure.PP_Oil_MinPressure := TwoWord_to_Float.Output;        // 52-53: 最低压力 PMin (MPa)
i := i + 2;

TwoWord_to_Float(word_low := HOLDING_REGISTER[i], word_high := HOLDING_REGISTER[i+1]);
GVL_PulsePressure.PP_Oil_Frequency := TwoWord_to_Float.Output;          // 54-55: 脉冲频率 (Hz)
i := i + 2;

TwoWord_to_Float(word_low := HOLDING_REGISTER[i], word_high := HOLDING_REGISTER[i+1]);
GVL_PulsePressure.PP_Oil_HighLimit := TwoWord_to_Float.Output;          // 56-57: 高压保护限值 (MPa)
i := i + 2;

TwoWord_to_Float(word_low := HOLDING_REGISTER[i], word_high := HOLDING_REGISTER[i+1]);
GVL_PulsePressure.PP_Oil_TargetCycles := TwoWord_to_Float.Output;       // 58-59: 目标循环次数
i := i + 2;

TwoWord_to_Float(word_low := HOLDING_REGISTER[i], word_high := HOLDING_REGISTER[i+1]);
GVL_PulsePressure.PP_Oil_RisePct := TwoWord_to_Float.Output;            // 60-61: 上升段占比
i := i + 2;

TwoWord_to_Float(word_low := HOLDING_REGISTER[i], word_high := HOLDING_REGISTER[i+1]);
GVL_PulsePressure.PP_Oil_HoldPct := TwoWord_to_Float.Output;            // 62-63: 保压段占比
i := i + 2;

TwoWord_to_Float(word_low := HOLDING_REGISTER[i], word_high := HOLDING_REGISTER[i+1]);
GVL_PulsePressure.PP_Oil_FallPct := TwoWord_to_Float.Output;            // 64-65: 下降段占比
i := i + 2;

TwoWord_to_Float(word_low := HOLDING_REGISTER[i], word_high := HOLDING_REGISTER[i+1]);
GVL_PulsePressure.PP_Oil_Overshoot := TwoWord_to_Float.Output;          // 66-67: 水锤波过冲峰倍数 (×P_Oper, 标准1.5; 写<1按1.5)
i := i + 2;

TwoWord_to_Float(word_low := HOLDING_REGISTER[i], word_high := HOLDING_REGISTER[i+1]);
GVL_PulsePressure.PP_Oil_RingPct := TwoWord_to_Float.Output;            // 68-69: 水锤波过冲后稳定段占比
i := i + 2;

TwoWord_to_Float(word_low := HOLDING_REGISTER[i], word_high := HOLDING_REGISTER[i+1]);
GVL_PulsePressure.PP_Oil_LowDwellPct := TwoWord_to_Float.Output;        // 70-71: 水锤波低保持段占比
i := i + 2;

TwoWord_to_Float(word_low := HOLDING_REGISTER[i], word_high := HOLDING_REGISTER[i+1]);
GVL_PulsePressure.PP_Oil_CycleReset := TwoWord_to_Float.Output;         // 72-73: 循环计数清零命令
i := i + 2;

TwoWord_to_Float(word_low := HOLDING_REGISTER[i], word_high := HOLDING_REGISTER[i+1]);
GVL_PulsePressure.PP_Oil_EnvPctP := TwoWord_to_Float.Output;            // 74-75: 正弦包络压力容差 ×PMax (≤0 用标准值 0.02)
i := i + 2;

TwoWord_to_Float(word_low := HOLDING_REGISTER[i], word_high := HOLDING_REGISTER[i+1]);
GVL_PulsePressure.PP_Oil_EnvPctT := TwoWord_to_Float.Output;            // 76-77: (已废弃) 原包络时间容差, 不参与计算, 地址保留
i := i + 2;

TwoWord_to_Float(word_low := HOLDING_REGISTER[i], word_high := HOLDING_REGISTER[i+1]);
GVL_PulsePressure.PP_Oil_WHRiseRate := TwoWord_to_Float.Output;         // 78-79: 水锤上升速率 (MPa/s, >0 启用斜坡上升; ≤0 用 RisePct 占比)
i := i + 2;

// 80-95: 保留 (8 字段)


// ===== [D] 控制器: ILC + PID (96-127) =====
i := 96;

TwoWord_to_Float(word_low := HOLDING_REGISTER[i], word_high := HOLDING_REGISTER[i+1]);
GVL_PulsePressure.PP_Oil_ILC_Enable := TwoWord_to_Float.Output;         // 96-97: ILC 使能
i := i + 2;

TwoWord_to_Float(word_low := HOLDING_REGISTER[i], word_high := HOLDING_REGISTER[i+1]);
GVL_PulsePressure.PP_Oil_ILC_MaxIter := TwoWord_to_Float.Output;        // 98-99: ILC 最大迭代次数
i := i + 2;

TwoWord_to_Float(word_low := HOLDING_REGISTER[i], word_high := HOLDING_REGISTER[i+1]);
GVL_PulsePressure.PP_Oil_ILC_LearningRate := TwoWord_to_Float.Output;   // 100-101: ILC 学习率 (0~1)
i := i + 2;

TwoWord_to_Float(word_low := HOLDING_REGISTER[i], word_high := HOLDING_REGISTER[i+1]);
GVL_PulsePressure.PP_Oil_PID_Kp := TwoWord_to_Float.Output;             // 102-103: PID 比例增益 Kp (V/MPa)
i := i + 2;

TwoWord_to_Float(word_low := HOLDING_REGISTER[i], word_high := HOLDING_REGISTER[i+1]);
GVL_PulsePressure.PP_Oil_PID_Ki := TwoWord_to_Float.Output;             // 104-105: PID 积分增益 Ki (V/MPa/s)
i := i + 2;

TwoWord_to_Float(word_low := HOLDING_REGISTER[i], word_high := HOLDING_REGISTER[i+1]);
GVL_PulsePressure.PP_Oil_PID_Kd := TwoWord_to_Float.Output;             // 106-107: PID 微分增益 Kd (V·s/MPa)
i := i + 2;

TwoWord_to_Float(word_low := HOLDING_REGISTER[i], word_high := HOLDING_REGISTER[i+1]);
GVL_PulsePressure.PP_Oil_Filter := TwoWord_to_Float.Output;          // 108-109: 油路压力滤波时间常数 (ms), 默认 100
i := i + 2;

TwoWord_to_Float(word_low := HOLDING_REGISTER[i], word_high := HOLDING_REGISTER[i+1]);
GVL_PulsePressure.PP_Oil_ILC_TrapShape := TwoWord_to_Float.Output;    // 110-111: 梯形ILC形态补偿使能 0/1 (默认0=仅端点补偿)
i := i + 2;

// 112-127: 保留 (8 字段)


// ===== [E] 液压站 (128-159) =====
i := 128;

TwoWord_to_Float(word_low := HOLDING_REGISTER[i], word_high := HOLDING_REGISTER[i+1]);
GVL_PulsePressure.PP_Hydro_HighLimit := TwoWord_to_Float.Output;        // 128-129: 液压站高压限值 (MPa)
i := i + 2;

TwoWord_to_Float(word_low := HOLDING_REGISTER[i], word_high := HOLDING_REGISTER[i+1]);
GVL_PulsePressure.PP_Hydro_TempLimit := TwoWord_to_Float.Output;        // 130-131: 油温保护限值 (°C)
i := i + 2;

TwoWord_to_Float(word_low := HOLDING_REGISTER[i], word_high := HOLDING_REGISTER[i+1]);
GVL_PulsePressure.PP_Hydro_PumpCmd := TwoWord_to_Float.Output;          // 132-133: 液压泵启停命令
i := i + 2;

TwoWord_to_Float(word_low := HOLDING_REGISTER[i], word_high := HOLDING_REGISTER[i+1]);
GVL_PulsePressure.PP_Hydro_MotorSpeed := TwoWord_to_Float.Output;       // 134-135: 电机转速设定 (rpm)
i := i + 2;

// 136-159: 保留 (12 字段)


// ===== [F] IO 控制 (160-191) =====
i := 160;

TwoWord_to_Float(word_low := HOLDING_REGISTER[i], word_high := HOLDING_REGISTER[i+1]);
GVL_PulsePressure.PP_IO_OutputBits := TwoWord_to_Float.Output;          // 160-161: 数字量输出控制
i := i + 2;

TwoWord_to_Float(word_low := HOLDING_REGISTER[i], word_high := HOLDING_REGISTER[i+1]);
GVL_PulsePressure.PP_IO_OilCircuitSel := TwoWord_to_Float.Output;       // 162-163: 油路选通
i := i + 2;

// 164-191: 保留 (14 字段)


// ===== [G] 设备控制 (192-255) =====
// 该区域的解析由 PRG_DeviceControl（待重写）负责。原始 HOLDING_REGISTER
// 直接保留在缓冲区, 新 PRG_DeviceControl 可直接按 bit/Float 访问解析。
//
// 建议地址分配 (占位约定):
//   192-193 : bit-packed 泵启停 (SMP/XH/HR1/HR2 × Start/Stop/Reset, 12 bits)
//   194-195 : bit-packed Pne_Valve YV1-YV13 (13 bits)
//   196-205 : 保留 (5 字段)
//   206-207 : SMP 压力设定 (MPa)
//   208-209 : SMP 流量设定
//   210-211 : HR_Pump1 频率设定
//   212-213 : HR_Pump2 频率设定
//   214-255 : 保留 (21 字段)


// ===== [Z] 256-1999: 未来扩展 =====

// ============================================================
// 复位 / 禁用
// ============================================================
IF bReset OR NOT bEnable THEN
    IF bReset THEN
        iIterCount        := 0;
        nUpdateCount      := 0;
        rPeakErrSum       := 0.0;
        rValleyErrSum     := 0.0;
        rRmsError         := 0.0;
        bConverged        := FALSE;
        rMidpoint         := 0.0;
        rHalfRange        := 0.0;
        rQuarter          := 0.0;
        rPrevTargetMax    := 0.0;
        rPrevTargetMin    := 0.0;
        rPrevTargetRange  := 0.0;
        rVMax             := 0.0;
        rVMin             := 0.0;
        bVInitialized     := FALSE;
        rActualPrev       := 0.0;
        rTargetPrev       := 0.0;
        // 8 段 α 默认均分
        FOR iBinK := 1 TO 8 DO
            rAlphaCmd[iBinK] := 0.125;
            rAlphaTgt[iBinK] := 0.125;
            rAlphaFb[iBinK]  := 0.125;
        END_FOR
        rVPeak := 0.0;
        rWHHoldActual := 0.0;
        rWHLowActual  := 0.0;
        rWH_T1 := 0.0; rWH_T2 := 0.0; rWH_T3 := 0.0; rWH_T4 := 0.0;
        rWHPeakErr := 0.0; rWHHoldErr := 0.0; rWHLowErr := 0.0;
    END_IF
    rOutput        := 0.0;
    rVirtualTarget := 0.0;
    rTargetMax     := -1.0E30;
    rTargetMin     :=  1.0E30;
    rActualMax     := -1.0E30;
    rActualMin     :=  1.0E30;
    rErrorSum2     := 0.0;
    iErrorCount    := 0;
    iBinTotal      := 0;
    FOR iBinK := 1 TO 8 DO
        iTgtBin[iBinK] := 0;
        iFbBin[iBinK]  := 0;
    END_FOR
    rWHOSPeakActual := -1.0E30;
    rWHHoldSum := 0.0; iWHHoldCount := 0;
    rWHLowSum  := 0.0; iWHLowCount  := 0;
    FOR iBinK := 1 TO 12 DO
        rShapeCorr[iBinK]   := 0.0;
        rShapeOobSum[iBinK] := 0.0;
        iShapeCnt[iBinK]    := 0;
    END_FOR
    bNewCyclePrev  := FALSE;
    bAnyOver100    := FALSE;
    bAnyOver80     := FALSE;
    bLearningArmed := FALSE;          // 复位后从"未学习"开始, 任何 100% 越界会触发首次 arming
    bDoLearnNow    := FALSE;
    IF NOT bEnable THEN
        RETURN;
    END_IF
END_IF

IF iPointsPerCycle < 10 THEN
    rOutput := 0.0; rVirtualTarget := 0.0; RETURN;
END_IF

// ============================================================
// 波形类型整定 (与 FB_WaveformGen 的 iWaveType 同编码)
//   0 = 正弦 (Fig.3) / 1 = 梯形 (Fig.1) / 2 = 水锤波 (Fig.2)
//   其他值与 FB_WaveformGen 的 ELSE 分支保持一致, 按正弦处理
// ============================================================
nWaveType := iWaveTypeIn;
IF nWaveType < 0 OR nWaveType > 2 THEN nWaveType := 0; END_IF

// ============================================================
// 新周期边界
// ============================================================
IF bNewCycle AND NOT bNewCyclePrev THEN

    // 包络门控 (迟滞型):
    //   - 进学习态: disarmed → armed, 触发条件 = 任一采样越 100% 包络
    //   - 出学习态: armed → disarmed, 触发条件 = 整个周期所有采样都在 80% 内包络
    //   - 不对称阈值避免临界处的 on/off 震荡。
    //   - 包络未配置 (rEnvUpper <= rEnvLower) 时退化为"每周期都学习", 兼容旧调用。
    IF nWaveType = 2 THEN
        // 水锤波: Fig.2 包络含大段自由窗(过冲+ring 窗、下降窗), 不能当学习门控
        // (actual 总在宽带内 → 永不触发 → 3 级端点学习不执行 → 无输出)。
        // 改为始终学习: 端点设定点(P_OS/PMax/PMin)误差为 P 型, 抵达后自然趋零,
        // iMaxIterations 仍可停学。
        bDoLearnNow := TRUE;
    ELSIF rEnvUpper <= rEnvLower THEN
        bDoLearnNow := TRUE;                 // 门控禁用 → 全部周期都学
    ELSIF bLearningArmed THEN
        // 当前在学习态: 本周期照学; 若 actual 已"全部回到 80% 内"则下周期起停学
        bDoLearnNow := TRUE;
        IF NOT bAnyOver80 THEN
            bLearningArmed := FALSE;         // 出学习态
        END_IF
    ELSE
        // 当前不在学习态: 若本周期任一采样越 100% 则进入学习态并立即学; 否则继续旁观
        IF bAnyOver100 THEN
            bLearningArmed := TRUE;          // 进学习态
            bDoLearnNow := TRUE;
        ELSE
            bDoLearnNow := FALSE;
        END_IF
    END_IF
    // 重置本周期累积标志
    bAnyOver100 := FALSE;
    bAnyOver80  := FALSE;

    // (水锤累加器复位下移到学习之后, 见 bNewCycle 块尾; 否则会"复位早于学习读取")

    // RMS
    IF iErrorCount > 0 THEN
        rRmsError := SQRT(rErrorSum2 / INT_TO_REAL(iErrorCount));
    END_IF
    rErrorSum2  := 0.0;
    iErrorCount := 0;

    // 8 段分布归一
    IF iBinTotal > 0 THEN
        rBinTotal := INT_TO_REAL(iBinTotal);
        FOR iBinK := 1 TO 8 DO
            rAlphaTgt[iBinK] := INT_TO_REAL(iTgtBin[iBinK]) / rBinTotal;
            rAlphaFb[iBinK]  := INT_TO_REAL(iFbBin[iBinK])  / rBinTotal;
        END_FOR
    END_IF
    FOR iBinK := 1 TO 8 DO
        iTgtBin[iBinK] := 0;
        iFbBin[iBinK]  := 0;
    END_FOR
    iBinTotal := 0;

    // 端点误差
    rPeakError   := rTargetMax - rActualMax;
    rValleyError := rTargetMin - rActualMin;

    // rMidpoint / rHalfRange
    rMidpoint  := (rTargetMax + rTargetMin) / 2.0;
    rHalfRange := (rTargetMax - rTargetMin) / 2.0;
    IF rHalfRange < 0.001 THEN rHalfRange := 0.001; END_IF
    rQuarter   := 0.5 * rHalfRange;

    rPrevTargetMax   := rTargetMax;
    rPrevTargetMin   := rTargetMin;
    rPrevTargetRange := rTargetMax - rTargetMin;

    rTargetMax := -1.0E30; rTargetMin :=  1.0E30;
    rActualMax := -1.0E30; rActualMin :=  1.0E30;

    iIterCount := iIterCount + 1;
    iIteration := iIterCount;

    IF iIterCount <= nWarmupCycles THEN
        nUpdateCount  := 0;
        rPeakErrSum   := 0.0;
        rValleyErrSum := 0.0;

    ELSIF NOT bConverged THEN
        IF NOT bVInitialized THEN
            rVMax := rPrevTargetMax;
            rVMin := rPrevTargetMin;
            IF nWaveType = 2 THEN
                // 水锤波: rTargetMax 是 P_OS 而非 PMax 保压目标
                rVPeak := rPrevTargetMax;
                IF rWHPMaxTarget > 0.001 THEN
                    rVMax := rWHPMaxTarget;       // PMax 保压目标
                END_IF
            END_IF
            bVInitialized := TRUE;
        END_IF

        IF iMaxIterations > 0 AND iIterCount >= iMaxIterations THEN
            bConverged := TRUE;
        ELSIF bDoLearnNow THEN  // 包络越界才学习 (本周期内 actual 曾越出 rEnvLower..rEnvUpper)
            // α 8 段自学习 (正弦 nWaveType=0)
            IF bAlphaEnable AND nWaveType = 0 THEN
                FOR iBinK := 1 TO 8 DO
                    rAlphaCmd[iBinK] := rAlphaCmd[iBinK]
                                     + rAlphaLR * (rAlphaTgt[iBinK] - rAlphaFb[iBinK]);
                    IF rAlphaCmd[iBinK] < ALPHA_Q_MIN THEN rAlphaCmd[iBinK] := ALPHA_Q_MIN; END_IF
                    IF rAlphaCmd[iBinK] > ALPHA_Q_MAX THEN rAlphaCmd[iBinK] := ALPHA_Q_MAX; END_IF
                END_FOR
                rAlphaSum := 0.0;
                FOR iBinK := 1 TO 8 DO
                    rAlphaSum := rAlphaSum + rAlphaCmd[iBinK];
                END_FOR
                IF rAlphaSum > 0.001 THEN
                    FOR iBinK := 1 TO 8 DO
                        rAlphaCmd[iBinK] := rAlphaCmd[iBinK] / rAlphaSum;
                    END_FOR
                END_IF
            END_IF

            // 端点幅值自学习（加法型）：水锤波由专用 3 级学习处理, 跳过通用路径
            IF nWaveType <> 2 THEN
                rPeakErrSum   := rPeakErrSum   + rPeakError;
                rValleyErrSum := rValleyErrSum + rValleyError;
                nUpdateCount  := nUpdateCount  + 1;
                IF nUpdateCount >= CYCLES_PER_UPDATE THEN
                    rVMax := rVMax + rLearningRate * (rPeakErrSum   / INT_TO_REAL(nUpdateCount));
                    rVMin := rVMin + rLearningRate * (rValleyErrSum / INT_TO_REAL(nUpdateCount));
                    IF rPrevTargetRange > 0.001 THEN
                        rLimit := V_RANGE_LIMIT_K * rPrevTargetRange;
                        IF rVMax > rPrevTargetMax + rLimit THEN rVMax := rPrevTargetMax + rLimit; END_IF
                        IF rVMax < rPrevTargetMax - rLimit THEN rVMax := rPrevTargetMax - rLimit; END_IF
                        IF rVMin > rPrevTargetMin + rLimit THEN rVMin := rPrevTargetMin + rLimit; END_IF
                        IF rVMin < rPrevTargetMin - rLimit THEN rVMin := rPrevTargetMin - rLimit; END_IF
                    END_IF
                    IF rVMax <= rVMin + 0.001 THEN
                        rVMax := rVMin + 0.001;
                    END_IF
                    rPeakErrSum   := 0.0;
                    rValleyErrSum := 0.0;
                    nUpdateCount  := 0;
                END_IF
            END_IF

            // 梯形形态修正: 12 段命令跟踪, 只向上 (系统能主动升压、只能被动泄压)
            //   实际低于指令(误差>0) → 抬高该段虚拟指令, 把实际顶上去贴指令;
            //   实际高于指令(下降/泄压段, 误差<0) → 该段触底归 0, 不下压(被动泄压不较劲);
            //   |误差|<死区 → 不动 (保持已学修正)。
            IF bTrapShapeEnable AND nWaveType = 1 THEN
                rLimit   := SHAPE_CORR_LIMIT_K * rPrevTargetRange;
                rShapeDB := SHAPE_CORR_DB_K   * rPrevTargetRange;
                FOR iBinK := 1 TO 12 DO
                    IF iShapeCnt[iBinK] > 0 THEN
                        rShapeErrSeg := rShapeOobSum[iBinK] / INT_TO_REAL(iShapeCnt[iBinK]);
                        IF rShapeErrSeg > rShapeDB OR rShapeErrSeg < -rShapeDB THEN
                            rShapeCorr[iBinK] := rShapeCorr[iBinK] + SHAPE_CORR_LR * rShapeErrSeg;
                            IF rShapeCorr[iBinK] < 0.0    THEN rShapeCorr[iBinK] := 0.0;    END_IF
                            IF rShapeCorr[iBinK] > rLimit THEN rShapeCorr[iBinK] := rLimit; END_IF
                        END_IF
                    END_IF
                END_FOR
            END_IF

            // ----- 水锤波 3 级端点学习 (vPeak / vMax / vMin 分别对应 P_OS / PMax / PMin) -----
            // 仅当对应段有足够样本时更新; 段 2 (ring) 与段 4 (fall) 是过渡段, 不学习
            IF nWaveType = 2 THEN
                // 段 1 峰: drive actual 抵达 rPrevTargetMax (= P_OS)
                IF rWHOSPeakActual > -1.0E29 THEN
                    rWHPeakErr := rPrevTargetMax - rWHOSPeakActual;
                    rVPeak := rVPeak + rLearningRate * rWHPeakErr;
                END_IF
                // 段 3 hold: drive actual 抵达 rWHPMaxTarget
                IF iWHHoldCount >= 2 THEN
                    rWHHoldActual := rWHHoldSum / INT_TO_REAL(iWHHoldCount);
                    IF rWHPMaxTarget > 0.001 THEN
                        rWHHoldErr := rWHPMaxTarget - rWHHoldActual;
                        rVMax := rVMax + rLearningRate * rWHHoldErr;
                    END_IF
                END_IF
                // 段 5 low: drive actual 抵达 rPrevTargetMin
                IF iWHLowCount >= 2 THEN
                    rWHLowActual := rWHLowSum / INT_TO_REAL(iWHLowCount);
                    rWHLowErr := rPrevTargetMin - rWHLowActual;
                    rVMin := rVMin + rLearningRate * rWHLowErr;
                END_IF
                // 限幅 (与通用端点学习一致)
                IF rPrevTargetRange > 0.001 THEN
                    rLimit := V_RANGE_LIMIT_K * rPrevTargetRange;
                    IF rVMax  > rPrevTargetMax + rLimit THEN rVMax  := rPrevTargetMax + rLimit; END_IF
                    IF rVMax  < rPrevTargetMax - rLimit THEN rVMax  := rPrevTargetMax - rLimit; END_IF
                    IF rVMin  > rPrevTargetMin + rLimit THEN rVMin  := rPrevTargetMin + rLimit; END_IF
                    IF rVMin  < rPrevTargetMin - rLimit THEN rVMin  := rPrevTargetMin - rLimit; END_IF
                    IF rVPeak > rPrevTargetMax + rLimit THEN rVPeak := rPrevTargetMax + rLimit; END_IF
                    IF rVPeak < rPrevTargetMax - rLimit THEN rVPeak := rPrevTargetMax - rLimit; END_IF
                END_IF
                IF rVMax  <= rVMin + 0.001 THEN rVMax  := rVMin + 0.001;  END_IF
                IF rVPeak < rVMax              THEN rVPeak := rVMax;        END_IF
                // 累加器复位已上提到 bNewCycle 入口 (无论是否学习都需要复位)
            END_IF
        END_IF
    END_IF

    // 缓存水锤波 5 段边界 (累积归一化相位; 上游已保证 sum = 1)
    IF nWaveType = 2 THEN
        rWH_T1 := rWHRiseFrac;
        rWH_T2 := rWH_T1 + rWHRingFrac;
        rWH_T3 := rWH_T2 + rWHHoldFrac;
        rWH_T4 := rWH_T3 + rWHFallFrac;
    END_IF

    // 水锤段累加器复位 (放在学习之后: 本周期学习已读完上一周期的累加值, 现清零供新周期累加)
    IF nWaveType = 2 THEN
        rWHOSPeakActual := -1.0E30;
        rWHHoldSum := 0.0; iWHHoldCount := 0;
        rWHLowSum  := 0.0; iWHLowCount  := 0;
    END_IF

    // 梯形形态修正累加器复位 (同样放在学习之后)
    IF nWaveType = 1 THEN
        FOR iBinK := 1 TO 12 DO
            rShapeOobSum[iBinK] := 0.0;
            iShapeCnt[iBinK]    := 0;
        END_FOR
    END_IF


END_IF

// ============================================================
// 每个采样点
// ============================================================

// 包络越界跟踪 (迟滞门控): 同步收集 100% 与 80% 两套越界标志, 由 bNewCycle 边界决定 arm/disarm
//   bAnyOver100: 至少一个采样越出 ARP1383C 100% 包络 (硬边界, 触发 arm)
//   bAnyOver80:  至少一个采样越出 80% 内包络 (软边界, 用于判定 disarm 条件: 全周期 ≤ 80%)
IF rEnvUpper > rEnvLower THEN
    rEnvInUp := rTargetRaw + ENV_INNER_RATIO * (rEnvUpper - rTargetRaw);
    rEnvInLo := rTargetRaw - ENV_INNER_RATIO * (rTargetRaw - rEnvLower);
    IF (rActual > rEnvUpper) OR (rActual < rEnvLower) THEN
        bAnyOver100 := TRUE;   // 100% 越界 → 蕴含 80% 越界
        bAnyOver80  := TRUE;
    ELSIF (rActual > rEnvInUp) OR (rActual < rEnvInLo) THEN
        bAnyOver80  := TRUE;   // 仅 80% 越界 (在 80%~100% 之间)
    END_IF
END_IF

// 周期相位
IF iPointsPerCycle > 0 THEN
    rPhi := INT_TO_REAL(iPointIndex) / INT_TO_REAL(iPointsPerCycle);
ELSE
    rPhi := 0.0;
END_IF
IF rPhi < 0.0 THEN rPhi := 0.0; END_IF
IF rPhi > 1.0 THEN rPhi := 1.0; END_IF

// 目标 / 反馈极值跟踪
IF rTargetRaw > rTargetMax THEN rTargetMax := rTargetRaw; END_IF
IF rTargetRaw < rTargetMin THEN rTargetMin := rTargetRaw; END_IF
IF rActual    > rActualMax THEN rActualMax := rActual;    END_IF
IF rActual    < rActualMin THEN rActualMin := rActual;    END_IF

rErrorSum2  := rErrorSum2 + (rTargetRaw - rActual) * (rTargetRaw - rActual);
iErrorCount := iErrorCount + 1;

// 方向检测
IF rTargetRaw >= rTargetPrev THEN bTgtRising := TRUE; ELSE bTgtRising := FALSE; END_IF
rTargetPrev := rTargetRaw;
IF rActual   >= rActualPrev THEN bFbRising  := TRUE; ELSE bFbRising  := FALSE; END_IF
rActualPrev := rActual;

// --------- 8 段分箱（正弦）---------
IF (nWaveType = 0) AND iIterCount >= 1 AND rHalfRange > 0.001 THEN
    iBinTotal := iBinTotal + 1;
    rTgtPos := rTargetRaw - rMidpoint;
    IF bTgtRising THEN
        IF      rTgtPos < -rQuarter THEN iBinK := 1;
        ELSIF   rTgtPos <  0.0      THEN iBinK := 2;
        ELSIF   rTgtPos <  rQuarter THEN iBinK := 3;
        ELSE                              iBinK := 4;
        END_IF
    ELSE
        IF      rTgtPos >  rQuarter THEN iBinK := 5;
        ELSIF   rTgtPos >  0.0      THEN iBinK := 6;
        ELSIF   rTgtPos > -rQuarter THEN iBinK := 7;
        ELSE                              iBinK := 8;
        END_IF
    END_IF
    iTgtBin[iBinK] := iTgtBin[iBinK] + 1;

    rFbPos := rActual - rMidpoint;
    IF bFbRising THEN
        IF      rFbPos < -rQuarter THEN iBinK := 1;
        ELSIF   rFbPos <  0.0      THEN iBinK := 2;
        ELSIF   rFbPos <  rQuarter THEN iBinK := 3;
        ELSE                             iBinK := 4;
        END_IF
    ELSE
        IF      rFbPos >  rQuarter THEN iBinK := 5;
        ELSIF   rFbPos >  0.0      THEN iBinK := 6;
        ELSIF   rFbPos > -rQuarter THEN iBinK := 7;
        ELSE                             iBinK := 8;
        END_IF
    END_IF
    iFbBin[iBinK] := iFbBin[iBinK] + 1;
END_IF

// --------- 水锤波 per-segment 反馈累加（按归一化相位切割）---------
// 段 1: 跟踪 actual 峰 (供 rVPeak 学习, 抵达 P_OS)
// 段 2: ring 过渡, 不学习
// 段 3: 累加均值 (供 rVMax 学习, 抵达 PMax 保压目标)
// 段 4: fall 过渡, 不学习
// 段 5: 累加均值 (供 rVMin 学习, 抵达 PMin 低保持)
IF nWaveType = 2 AND iIterCount >= 1 THEN
    IF rPhi < rWH_T1 THEN
        IF rActual > rWHOSPeakActual THEN rWHOSPeakActual := rActual; END_IF
    ELSIF rPhi >= rWH_T2 AND rPhi < rWH_T3 THEN
        rWHHoldSum   := rWHHoldSum + rActual;
        iWHHoldCount := iWHHoldCount + 1;
    ELSIF rPhi >= rWH_T4 THEN
        rWHLowSum    := rWHLowSum + rActual;
        iWHLowCount  := iWHLowCount + 1;
    END_IF
END_IF

// --------- 梯形形态修正 per-segment 命令跟踪误差累加 (12 等相位段) ---------
IF bTrapShapeEnable AND nWaveType = 1 AND iIterCount >= 1 THEN
    iShapeSeg := REAL_TO_INT(rPhi * 12.0);
    IF iShapeSeg < 0  THEN iShapeSeg := 0;  END_IF
    IF iShapeSeg > 11 THEN iShapeSeg := 11; END_IF
    iShapeSeg := iShapeSeg + 1;
    rShapeOobSum[iShapeSeg] := rShapeOobSum[iShapeSeg] + (rTargetRaw - rActual);  // 指令-实际; >0=实际偏低
    iShapeCnt[iShapeSeg]    := iShapeCnt[iShapeSeg] + 1;
END_IF

// ============================================================
// 输出生成
// ============================================================

// 暖机期 / 首次学习窗未到 / 目标无幅值：直通
IF iIterCount <= nWarmupCycles OR rPrevTargetRange < 0.001 THEN
    rVirtualTarget := rTargetRaw;
    rOutput        := 0.0;
    bNewCyclePrev  := bNewCycle;
    RETURN;
END_IF

IF NOT bVInitialized THEN
    rVirtualTarget := rTargetRaw;
    rOutput        := 0.0;
    bNewCyclePrev  := bNewCycle;
    RETURN;
END_IF

// 源波形 rSourceTarget：
//   正弦(0) → α 8 段相位重映射后重建
//   水锤(2) → 5 段直接重构并提前返回
//   梯形(1) → α 12 段相位重映射 + 梯形模板
IF nWaveType = 0 THEN
    rT1 := rAlphaCmd[1];
    rT2 := rT1 + rAlphaCmd[2];
    rT3 := rT2 + rAlphaCmd[3];
    rT4 := rT3 + rAlphaCmd[4];
    rT5 := rT4 + rAlphaCmd[5];
    rT6 := rT5 + rAlphaCmd[6];
    rT7 := rT6 + rAlphaCmd[7];

    IF rPhi < rT1 THEN
        IF rT1 > 0.001 THEN rPhiStd := rPhi / rT1 * 0.125; ELSE rPhiStd := 0.0; END_IF
    ELSIF rPhi < rT2 THEN
        rDelta := rT2 - rT1;
        IF rDelta > 0.001 THEN rPhiStd := 0.125 + (rPhi - rT1) / rDelta * 0.125; ELSE rPhiStd := 0.125; END_IF
    ELSIF rPhi < rT3 THEN
        rDelta := rT3 - rT2;
        IF rDelta > 0.001 THEN rPhiStd := 0.250 + (rPhi - rT2) / rDelta * 0.125; ELSE rPhiStd := 0.250; END_IF
    ELSIF rPhi < rT4 THEN
        rDelta := rT4 - rT3;
        IF rDelta > 0.001 THEN rPhiStd := 0.375 + (rPhi - rT3) / rDelta * 0.125; ELSE rPhiStd := 0.375; END_IF
    ELSIF rPhi < rT5 THEN
        rDelta := rT5 - rT4;
        IF rDelta > 0.001 THEN rPhiStd := 0.500 + (rPhi - rT4) / rDelta * 0.125; ELSE rPhiStd := 0.500; END_IF
    ELSIF rPhi < rT6 THEN
        rDelta := rT6 - rT5;
        IF rDelta > 0.001 THEN rPhiStd := 0.625 + (rPhi - rT5) / rDelta * 0.125; ELSE rPhiStd := 0.625; END_IF
    ELSIF rPhi < rT7 THEN
        rDelta := rT7 - rT6;
        IF rDelta > 0.001 THEN rPhiStd := 0.750 + (rPhi - rT6) / rDelta * 0.125; ELSE rPhiStd := 0.750; END_IF
    ELSE
        rDelta := 1.0 - rT7;
        IF rDelta > 0.001 THEN rPhiStd := 0.875 + (rPhi - rT7) / rDelta * 0.125; ELSE rPhiStd := 0.875; END_IF
    END_IF

    // 正弦：基波形 = (1 - cos(2π·φ_std)) / 2
    rWarpedY := (1.0 - COS(TWO_PI * rPhiStd)) / 2.0;
    rSourceTarget := rPrevTargetMin + rWarpedY * rPrevTargetRange;

ELSIF nWaveType = 2 THEN
    // 水锤波: 5 段直接重构 (3 级端点学习 vPeak / vMax / vMin, 不走仿射重映射)
    //   段 1: rVPeak                       (过冲峰)
    //   段 2: rVMax                        (ring 衰减后立即落到 PMax)
    //   段 3: rVMax                        (PMax 保压)
    //   段 4+5: rVMin                      (阶跃下降: 指令直落无斜率 + PMin 低保持)
    IF rPhi < rWH_T1 THEN
        rVirtualTarget := rVPeak;
    ELSIF rPhi < rWH_T2 THEN
        rVirtualTarget := rVMax;
    ELSIF rPhi < rWH_T3 THEN
        rVirtualTarget := rVMax;
    ELSE
        rVirtualTarget := rVMin;
    END_IF
    rOutput := rVirtualTarget - rTargetRaw;
    bNewCyclePrev := bNewCycle;
    RETURN;

ELSIF nWaveType = 1 THEN
    // 梯形：端点补偿(仿射重映射到 [vMin,vMax]) + 末尾按上下包络逐段叠加 rShapeCorr 形态修正
    rSourceTarget := rTargetRaw;

ELSE
    rSourceTarget := rTargetRaw;
END_IF

// 仿射重映射 [tMin, tMax] → [vMin, vMax]
rNorm          := (rSourceTarget - rPrevTargetMin) / rPrevTargetRange;
rVirtualTarget := rVMin + rNorm * (rVMax - rVMin);

// 梯形形态修正: 端点重映射之上, 按当前相位段叠加 rShapeCorr (≥0, 命令跟踪只向上)
// 纯幅值修正, 无相位重映射 → 结构上不会出现 α-12 那种半周期反相
IF bTrapShapeEnable AND (nWaveType = 1) THEN
    iShapeSeg := REAL_TO_INT(rPhi * 12.0);
    IF iShapeSeg < 0  THEN iShapeSeg := 0;  END_IF
    IF iShapeSeg > 11 THEN iShapeSeg := 11; END_IF
    rVirtualTarget := rVirtualTarget + rShapeCorr[iShapeSeg + 1];
END_IF

rOutput := rVirtualTarget - rTargetRaw;

bNewCyclePrev := bNewCycle;

// 经典 PID 控制器：比例 + 积分抗饱和(back-calculation) + 滤波微分。


// ============================================================
// 复位
// ============================================================
IF bReset OR NOT bEnable THEN
    rIntegral := 0.0;
    rDfilt := 0.0;
    rErrorPrev := 0.0;
    rOutputRaw := 0.0;
    rOutput := 0.0;
    rPID_P := 0.0;
    rPID_I := 0.0;
    rPID_D := 0.0;
    RETURN;
END_IF

// 周期保护
IF rDt < 1.0E-6 THEN
    rOutput := 0.0;
    RETURN;
END_IF

// ============================================================
// PID 控制律: u = Kp*e + Ki*∫e*dt + Kd*de/dt(filtered)
//
// 微分项用一阶低通滤波避免噪声放大:
//   D_filt(k) = (1 - dt/Tf)*D_filt(k-1) + (Kd/Tf)*(e - e_prev)
//   Tf → 0 时退化为纯微分
//
// 积分抗饱和 (back-calculation):
//   当输出饱和时用饱和误差反馈修正积分项:
//   ∫e += (e + Kb*(u_sat - u_raw)) * dt
//   Kb 越大抗饱和越快
// ============================================================

// --- 比例项 ---
rPID_P := rPID_Kp * rError;

// --- 微分项 (带滤波) ---
IF rPID_Tf > rDt THEN
    rDfilt := rDfilt + (rDt / rPID_Tf) * (rPID_Kd * (rError - rErrorPrev) / rDt - rDfilt);
ELSE
    rDfilt := rPID_Kd * (rError - rErrorPrev) / rDt;
END_IF
rPID_D := rDfilt;

// --- 积分项 (带抗饱和) ---
rIntegral := rIntegral + rPID_Ki * (rError + rPID_Kb * (rOutput - rOutputRaw)) * rDt;
IF rIntegral > OUTPUT_LIMIT THEN rIntegral := OUTPUT_LIMIT; END_IF
IF rIntegral < -OUTPUT_LIMIT THEN rIntegral := -OUTPUT_LIMIT; END_IF
rPID_I := rIntegral;

// --- 合成输出 ---
rOutputRaw := rPID_P + rPID_I + rPID_D;

// --- 输出限幅 ---
rUfb := rOutputRaw;
IF rUfb > OUTPUT_LIMIT THEN rUfb := OUTPUT_LIMIT; END_IF
IF rUfb < -OUTPUT_LIMIT THEN rUfb := -OUTPUT_LIMIT; END_IF
rOutput := rUfb;

// 保存上一步误差
rErrorPrev := rError;

// 根据相位计算单点目标压力。被 FB_WaveformGen 在多处复用：
//   - 主波形 (当前相位)
//   - MFF 超前 (φ + lead·Δφ)
// 段宽参数 rR/rH/rF/rRing/rPeakOS 在调用前已由调用方归一化并保护过。


CASE iWaveType OF

0:  // 正弦波 (-cos 形式，从 PMin 平滑起步)
    FN_PulseWave := (rPMax + rPMin) / 2.0
                    - (rPMax - rPMin) / 2.0 * COS(2.0 * PI * rPhaseIn);

1:  // 梯形波
    IF rPhaseIn < rR THEN
        FN_PulseWave := rPMin + (rPMax - rPMin) * (rPhaseIn / rR);
    ELSIF rPhaseIn < (rR + rH) THEN
        FN_PulseWave := rPMax;
    ELSIF rPhaseIn < (rR + rH + rF) THEN
        FN_PulseWave := rPMax - (rPMax - rPMin) * ((rPhaseIn - rR - rH) / rF);
    ELSE
        FN_PulseWave := rPMin;
    END_IF

2:  // ARP1383C 水锤波 (上升斜坡到过冲峰 / 回 P_Oper / 保压 / 阶跃下降+低保持)
    // 上升段: 从 PMin 按上升速率斜坡爬升到过冲峰 P_OS (rR = 速率换算的相位宽,
    //   到峰即 ph=rR); 到峰后立刻回 P_Oper(PMax); 下降为阶跃直落 PMin
    //   (rF 仅作包络自由窗, 泄压靠系统自然响应)
    IF rPhaseIn < rR THEN
        IF rR > 0.0001 THEN
            FN_PulseWave := rPMin + (rPeakOS - rPMin) * (rPhaseIn / rR);   // 斜坡上升到 P_OS
        ELSE
            FN_PulseWave := rPeakOS;                                       // 宽度退化保护: 阶跃
        END_IF
    ELSIF rPhaseIn < (rR + rRing) THEN
        FN_PulseWave := rPMax;
    ELSIF rPhaseIn < (rR + rRing + rH) THEN
        FN_PulseWave := rPMax;
    ELSE
        FN_PulseWave := rPMin;
    END_IF

ELSE
    // 默认正弦
    FN_PulseWave := (rPMax + rPMin) / 2.0
                    - (rPMax - rPMin) / 2.0 * COS(2.0 * PI * rPhaseIn);
END_CASE

// 限幅保护
IF FN_PulseWave < 0.0 THEN FN_PulseWave := 0.0; END_IF
